content/adventure.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/adventure.schema.json",
  "title": "Ignis Aura adventure",
  "description": "An adventure hook: the prologue read aloud when a game starts, its goal, and how it sets the game up. See content/README.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["id", "status", "party", "title", "teaser", "story", "goal"],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "description": "Its id: lowercase words joined by hyphens. Other content refers to it by this.",
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "status": {
      "description": "draft while you're writing it, ready when it's complete.",
      "enum": ["draft", "ready"]
    },
    "party": {
      "description": "Who it's written for: one hero, a group, or either.",
      "enum": ["solo", "group", "any"]
    },
    "title": {
      "description": "The adventure's name, as players see it when starting a game.",
      "type": "string",
      "minLength": 1
    },
    "teaser": {
      "description": "One line shown when choosing an adventure.",
      "type": "string",
      "minLength": 1
    },
    "story": {
      "description": "The prologue, one paragraph per entry, read aloud a paragraph at a time. {hero} / {heroes} become the players' names.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "string",
        "minLength": 1
      }
    },
    "goal": {
      "description": "What the heroes must do, as one sentence. Shown at the end of the prologue and on the Game Over screen.",
      "type": "string",
      "minLength": 1
    },
    "quest": {
      "description": "The goal as steps the game can check, in order; finishing the last one wins the game for the party. A step is done when one hero meets everything in `done` at once, when an encounter's outcome gives a {\"type\": \"quest\", \"step\": id} effect, or when the Keeper marks it done. A step without `done` waits for an encounter or the Keeper.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "text"],
        "properties": {
          "id": {
            "description": "The step's id; a quest effect on an outcome completes it by this.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "text": {
            "description": "What the heroes must do, as players see it.",
            "type": "string",
            "minLength": 1
          },
          "done": {
            "description": "Optional: when the app ticks the step off by itself (standing on a place, holding an item, having the gold). Without it, the step is done by a quest effect or the Keeper.",
            "type": "object",
            "additionalProperties": false,
            "minProperties": 1,
            "properties": {
              "at": {
                "description": "A hero stands on this place: \"<tile>.<location>\".",
                "type": "string",
                "pattern": "^[a-z0-9-]+\\.[a-z0-9-]+$"
              },
              "has": {
                "description": "That hero carries this item (in the pack or worn).",
                "type": "string",
                "minLength": 1
              },
              "gold": {
                "description": "That hero has at least this much gold.",
                "type": "integer",
                "minimum": 1
              }
            }
          }
        }
      }
    },
    "reward": {
      "description": "What finishing the quest brings: its words on the victory screen, and effects for every hero still in the game.",
      "$ref": "schema.json#/definitions/outcome"
    },
    "deadline": {
      "description": "The quest fails if it isn't finished by the end of this round: the game ends, and the failure outcome happens.",
      "type": "object",
      "additionalProperties": false,
      "required": ["byRound"],
      "properties": {
        "byRound": {
          "description": "The last round to finish it in.",
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "failure": {
      "description": "What failing the quest brings (out of time): its words on the Game Over screen, and effects for every hero.",
      "$ref": "schema.json#/definitions/outcome"
    },
    "setup": {
      "description": "How the adventure sets up the game. Everything is optional.",
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "mode": {
          "description": "The suggested game mode; players can still change it.",
          "type": "object",
          "additionalProperties": false,
          "required": ["id"],
          "properties": {
            "id": {
              "description": "Which game mode the adventure starts in.",
              "enum": ["standard", "timed"]
            },
            "rounds": {
              "description": "How many rounds the game lasts, if it has a round limit.",
              "type": "integer",
              "minimum": 1,
              "maximum": 50
            }
          }
        },
        "start": {
          "description": "Where every hero's piece starts: on the digital board, on free squares of this location (the first tile's start squares if it has too few), and told to the players before play.",
          "type": "object",
          "additionalProperties": false,
          "required": ["location"],
          "properties": {
            "location": {
              "description": "<tile>.<location>, e.g. civilization.sewers",
              "type": "string",
              "pattern": "^[a-z0-9-]+\\.[a-z0-9-]+$"
            },
            "note": {
              "description": "Shown to the players at the start: where to put their pieces.",
              "type": "string",
              "minLength": 1
            }
          }
        },
        "inventory": {
          "description": "What each hero starts with, as effects (gold, items, cards).",
          "type": "array",
          "items": {
            "$ref": "schema.json#/definitions/effect"
          }
        },
        "firstRound": {
          "description": "Special rules for the first round, shown before play and on Home during round 1.",
          "type": "array",
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "notes": {
      "description": "Author notes. Never shown in the app.",
      "type": "string"
    }
  }
}

content/adventures/a-simple-delivery.jso:
{
  "$schema": "../adventure.schema.json",
  "id": "a-simple-delivery",
  "status": "draft",
  "party": "any",
  "title": "A Simple Delivery",
  "teaser": "Carry one crate across the realm. Don't open it. It's very simple.",
  "story": [
    "The job sounded easy. A hooded merchant in the city paid good coin to have one crate carried to the old keep in the dungeon lands. One crate. No questions.",
    "The crate is heavy. The crate is warm. Occasionally, the crate hums.",
    "{heroes}: the merchant was very clear about one thing. Whatever happens, whatever you hear, you must not open the crate."
  ],
  "goal": "Deliver the crate to the Dungeon Keeps without opening it.",
  "quest": [
    {
      "id": "deliver-the-crate",
      "text": "Deliver the crate to the Dungeon Keeps, unopened",
      "done": { "at": "dungeon.keeps", "has": "Suspicious Crate" }
    }
  ],
  "setup": {
    "mode": { "id": "standard" },
    "start": { "location": "civilization.cities" },
    "inventory": [
      { "type": "gold", "amount": 4 },
      { "type": "item", "name": "Suspicious Crate" }
    ]
  },
  "notes": "Draft by Claude for Andrew to rewrite. Works for one hero or a party: {heroes} becomes the names either way. The quest steps are Claude's drafts (0.7.0) from the goal."
}

content/adventures/feast-of-the-unwelcom:
{
  "$schema": "../adventure.schema.json",
  "id": "feast-of-the-unwelcome-dead",
  "status": "draft",
  "party": "group",
  "title": "Feast of the Unwelcome Dead",
  "teaser": "The Baron has risen for his annual banquet. You're on the menu.",
  "story": [
    "Once a year, on the longest night, Baron Grimsworth rises from his mound and throws a feast. He has done this for four hundred years. He has never once been invited back.",
    "This year the Baron has decided that if nobody will come to his feast, his feast will come to everybody. His guests are already shambling out of the burial mounds, napkins tucked into their ribcages.",
    "{heroes}, you were passing through the mounds at entirely the wrong moment. Find the Baron's resting place and put him back in it, before dawn."
  ],
  "goal": "Find Baron Grimsworth in the Mass Burial Mounds and lay him to rest before dawn (the last round).",
  "quest": [
    {
      "id": "find-the-baron",
      "text": "Find Baron Grimsworth in the Mass Burial Mounds"
    },
    { "id": "lay-him-to-rest", "text": "Lay Baron Grimsworth to rest" }
  ],
  "setup": {
    "mode": { "id": "timed", "rounds": 8 },
    "start": { "location": "chaos.mass-burial-mounds" },
    "inventory": [
      { "type": "gold", "amount": 2 },
      { "type": "item", "name": "Shovel" }
    ],
    "firstRound": ["The dead are hungry: the first hero to fail a roll this round loses 2 gold."]
  },
  "notes": "Draft by Claude for Andrew to rewrite. The quest steps are Claude's drafts (0.7.0) from the goal."
}

content/adventures/the-debt-collector.js:
{
  "$schema": "../adventure.schema.json",
  "id": "the-debt-collector",
  "status": "draft",
  "party": "solo",
  "title": "The Debt Collector",
  "teaser": "You owe the wrong people money. They'd like it back. Today.",
  "story": [
    "It was a fine plan, {hero}. Borrow fifty gold from the Velvet Hand, buy a cart of exotic cheeses, sell them at a tidy profit. Nobody told you the cheeses were alive.",
    "Now the cheeses are gone, the gold is gone, and a very polite man with very large friends has explained that the Velvet Hand expects repayment before the tenth bell.",
    "You wake in the sewers beneath the city with a rusty dagger, three coins, and a growing sense that you should start running."
  ],
  "goal": "Return to the Cities with at least 30 gold before the last round ends.",
  "quest": [
    {
      "id": "pay-the-debt",
      "text": "Return to the Cities with at least 30 gold",
      "done": { "at": "civilization.cities", "gold": 30 }
    }
  ],
  "setup": {
    "mode": { "id": "timed", "rounds": 10 },
    "start": { "location": "civilization.sewers", "note": "You wake among the rats." },
    "inventory": [
      { "type": "gold", "amount": 3 },
      { "type": "item", "name": "Rusty Dagger" }
    ],
    "firstRound": ["The Velvet Hand is watching: you may not leave Civilization this round."]
  },
  "notes": "Draft by Claude for Andrew to rewrite. The quest steps are Claude's drafts (0.7.0) from the goal."
}

content/adventures/the-drowned-bell.json:
{
  "$schema": "../adventure.schema.json",
  "id": "the-drowned-bell",
  "status": "draft",
  "party": "group",
  "title": "The Drowned Bell",
  "teaser": "A bell tolls beneath the sea, and the dead are listening.",
  "story": [
    "Three nights ago, fishermen heard a bell ringing beneath the waves where no bell has any right to be.",
    "Each night it rings a little louder. Each night, a few more graves in the burial mounds are found empty, their occupants walking slowly, patiently, towards the shore.",
    "{heroes}: you are the only ones foolish enough, or perhaps brave enough, to answer the fishing village's call for help. The bell will ring twelve times more. After that, nobody is quite sure what happens, and nobody wants to find out."
  ],
  "goal": "Silence the Drowned Bell before the twelfth round ends.",
  "quest": [{ "id": "silence-the-bell", "text": "Silence the Drowned Bell" }],
  "setup": {
    "mode": { "id": "timed", "rounds": 12 },
    "start": {
      "location": "wilderness.oceans",
      "note": "Each hero starts on a different space along the shore."
    },
    "inventory": [
      { "type": "gold", "amount": 5 },
      { "type": "card", "name": "Into the Deep" }
    ],
    "firstRound": ["The tide is out: the Oceans can be crossed on foot this round."]
  },
  "notes": "Draft by Claude for Andrew to rewrite. The quest steps are Claude's drafts (0.7.0) from the goal."
}

content/adventures/the-last-lantern.json:
{
  "$schema": "../adventure.schema.json",
  "id": "the-last-lantern",
  "status": "draft",
  "party": "solo",
  "title": "The Last Lantern",
  "teaser": "Your village's light is dying. Something in the dark is glad.",
  "story": [
    "For three hundred years the Lantern of Hollowmere has burned in the village square, and for three hundred years the things in the forest have stayed in the forest.",
    "Last night the flame shrank to the size of a candle. This morning, something left footprints on the chapel roof.",
    "The elders say only the Ember of Ages, kept high in a forgotten dungeon tower, can rekindle it. The elders also say they're too old to go. So it falls to you, {hero}."
  ],
  "goal": "Find the Ember of Ages in the Dungeon Towers and carry it back to the Forests.",
  "quest": [
    {
      "id": "reach-the-towers",
      "text": "Reach the Dungeon Towers",
      "done": { "at": "dungeon.towers" }
    },
    {
      "id": "find-the-ember",
      "text": "Find the Ember of Ages",
      "done": { "has": "Ember of Ages" }
    },
    {
      "id": "carry-it-home",
      "text": "Carry the Ember of Ages back to the Forests",
      "done": { "at": "wilderness.forests", "has": "Ember of Ages" }
    }
  ],
  "setup": {
    "mode": { "id": "standard" },
    "start": { "location": "wilderness.forests" },
    "inventory": [
      { "type": "gold", "amount": 5 },
      { "type": "item", "name": "Flickering Lantern" }
    ],
    "firstRound": ["The night is dark: all Survival rolls this round are 4 harder."]
  },
  "notes": "Draft by Claude for Andrew to rewrite. The quest steps are Claude's drafts (0.7.0) from the goal."
}

content/board.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/board.schema.json",
  "title": "Ignis Aura board",
  "description": "The digital board: where each tile lies, which symbol is on every square, the journey between tiles, and where heroes start. A hero crosses from one tile to the next on the journey only through the edge the two share.",
  "type": "object",
  "additionalProperties": false,
  "required": ["size", "journey", "start", "tiles"],
  "properties": {
    "$schema": { "type": "string" },
    "size": {
      "description": "How many squares across (and down) each tile is.",
      "type": "integer",
      "minimum": 2,
      "maximum": 16
    },
    "journey": {
      "description": "Tile ids in the order heroes travel them. Each tile connects to the one before and after it, through their shared edge; no others connect.",
      "type": "array",
      "minItems": 1,
      "uniqueItems": true,
      "items": { "type": "string" }
    },
    "start": {
      "description": "Where heroes start, as [x, y] squares on the whole board, in turn order. At least one per player who can join.",
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/definitions/square" }
    },
    "tiles": {
      "description": "The four tiles, where each sits on the board, and what's printed on each square.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["tileId", "origin", "squares"],
        "properties": {
          "tileId": { "description": "The tile's id, as in content/tiles/.", "type": "string" },
          "origin": {
            "description": "The tile's top-left square on the whole board, as [x, y].",
            "$ref": "#/definitions/square"
          },
          "squares": {
            "description": "The tile's squares, row by row from the top: each one the id of a location on this tile.",
            "type": "array",
            "items": { "type": "array", "items": { "type": "string" } }
          }
        }
      }
    },
    "regions": {
      "description": "Regions: groups of nearby squares under one name, like Emberlight's city, sewers and graveyard. A region's squares must touch (diagonals count); a square is in one region at most, and many are in none.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "name", "squares"],
        "properties": {
          "id": {
            "description": "Its id: encounters tied to this region name it.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "name": {
            "description": "What players see, e.g. 'Emberlight'.",
            "type": "string",
            "minLength": 1
          },
          "squares": {
            "description": "Its squares, as [x, y] on the whole board.",
            "type": "array",
            "minItems": 1,
            "items": { "$ref": "#/definitions/square" }
          }
        }
      }
    },
    "named": {
      "description": "Named places: single squares with a name of their own, like the City of Emberlight. Encounters can be tied to one.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "name", "square"],
        "properties": {
          "id": {
            "description": "Its id: encounters tied to this place name it.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "name": {
            "description": "What players see, e.g. 'City of Emberlight'.",
            "type": "string",
            "minLength": 1
          },
          "square": {
            "description": "Its square, as [x, y] on the whole board.",
            "$ref": "#/definitions/square"
          }
        }
      }
    },
    "closed": {
      "description": "Squares closed for now: shown locked, and no hero can step onto them.",
      "type": "array",
      "items": { "$ref": "#/definitions/square" }
    }
  },
  "definitions": {
    "square": {
      "type": "array",
      "items": { "type": "integer", "minimum": 0 },
      "minItems": 2,
      "maxItems": 2
    }
  }
}

content/changelog.json:
{
  "$schema": "./changelog.schema.json",
  "notes": "Shown once, on a scroll, when a player opens the app after updating to that version. Add the next version at the top before releasing it.",
  "versions": [
    {
      "version": "0.7.0",
      "title": "The gameplay loop",
      "notes": [
        "Win by completing your adventure's quest, step by step.",
        "Class abilities: spend your resource for bonuses and healing, stronger as they rank up.",
        "Loot: open your loot pouch, keep a hidden pocket safe from thieves.",
        "Day and night: two rounds each, and some encounters only come out after dark.",
        "Encounters from Common to Legendary, some only once a game.",
        "Hubs: choose where to head in a city square, without ending your turn.",
        "A quest log, from the golden \"!\": your party's quest, side quests and personal quests.",
        "Starlight: join the stars while you wait for your turn."
      ]
    }
  ]
}

content/changelog.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/changelog.schema.json",
  "title": "Ignis Aura: what's new",
  "description": "What each version brings, shown once on a scroll when a player opens the app after updating to it.",
  "type": "object",
  "additionalProperties": false,
  "required": ["versions"],
  "properties": {
    "$schema": { "type": "string" },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    },
    "versions": {
      "description": "Newest first. Only the version a player has just updated to is shown.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["version", "title", "notes"],
        "properties": {
          "version": {
            "description": "The app's version, exactly as in app.json, e.g. 0.7.0.",
            "type": "string",
            "pattern": "^\\d+\\.\\d+\\.\\d+$"
          },
          "title": {
            "description": "A short headline for the update.",
            "type": "string",
            "minLength": 1
          },
          "notes": {
            "description": "What's new, one line each.",
            "type": "array",
            "minItems": 1,
            "items": { "type": "string", "minLength": 1 }
          }
        }
      }
    }
  }
}

