content/events.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/events.schema.json",
  "title": "Ignis Aura Keeper events",
  "description": "Special events the Keeper can set off for the whole table: the turn pauses, everyone sees the scene, and each hero faces its challenge.",
  "type": "object",
  "additionalProperties": false,
  "required": ["status", "events"],
  "properties": {
    "$schema": { "type": "string" },
    "status": {
      "description": "draft while it's being worked on; ready once it's finished and checked.",
      "enum": ["draft", "ready"]
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    },
    "events": {
      "description": "Every event the Keeper can choose from.",
      "type": "array",
      "items": { "$ref": "#/definitions/event" }
    }
  },
  "definitions": {
    "event": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "status", "name", "text", "mood"],
      "properties": {
        "id": {
          "description": "Its id: lowercase words joined by hyphens.",
          "type": "string",
          "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
        },
        "status": {
          "description": "draft while it's being worked on; ready once it's finished and checked.",
          "enum": ["draft", "ready"]
        },
        "name": {
          "description": "The event's name, in the Keeper's menu and as its heading.",
          "type": "string",
          "minLength": 1
        },
        "text": {
          "description": "The scene every player sees when it strikes.",
          "type": "string",
          "minLength": 1
        },
        "mood": {
          "description": "What fills the screen behind the words: fog sweeping through the night, embers, a storm's flashes, or stars.",
          "enum": ["fog", "embers", "storm", "stars"]
        },
        "targets": {
          "description": "Who faces it: everyone (the default), only the player whose turn it is, or everyone else.",
          "enum": ["everyone", "current", "others"]
        },
        "challenge": {
          "description": "What each hero faces: a quicktime or a roll, with a quick difficulty. Leave it out and the success outcome just happens to everyone.",
          "type": "object",
          "required": ["type"],
          "properties": { "type": { "enum": ["quicktime", "roll"] } },
          "allOf": [
            {
              "if": { "type": "object", "properties": { "type": { "const": "quicktime" } } },
              "then": { "$ref": "schema.json#/definitions/quicktimeAction" }
            },
            {
              "if": { "type": "object", "properties": { "type": { "const": "roll" } } },
              "then": { "$ref": "schema.json#/definitions/rollAction" }
            }
          ]
        },
        "success": {
          "description": "What comes of it for a hero who succeeds (or, with no challenge, for everyone).",
          "$ref": "schema.json#/definitions/outcome"
        },
        "failure": {
          "description": "What comes of it for a hero who fails.",
          "$ref": "schema.json#/definitions/outcome"
        },
        "limits": {
          "description": "How often the Keeper can set it off. Leave out any of these to use the defaults in rules.json (once a game, 3 rounds apart).",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "perGame": {
              "description": "Times a game.",
              "type": "integer",
