{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/fate.schema.json",
  "title": "Ignis Aura Chest of Fate",
  "description": "The Fate cards in the physical Chest of Fate. Each card's face shows its runes; entering them in the app reveals and applies its reward. See content/README.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["status", "cards"],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "status": {
      "description": "draft while it's being worked on; ready once it's finished and checked.",
      "enum": ["draft", "ready"]
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    },
    "cards": {
      "description": "Every card in the physical Chest of Fate.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "runes", "name", "rarity", "text", "effects"],
        "properties": {
          "id": {
            "description": "Its id: lowercase words joined by hyphens. Other content refers to it by this.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "runes": {
            "description": "The four runes on the card's face, left to right. Any two cards must differ in at least two runes.",
