            "minItems": 4,
            "maxItems": 4,
            "items": {
              "$ref": "schema.json#/definitions/rune"
            }
          },
          "name": {
            "description": "The card's name, as printed.",
            "type": "string",
            "minLength": 1
          },
          "rarity": {
            "description": "How rare the card is, as printed on it.",
            "enum": ["common", "uncommon", "rare", "legendary"]
          },
          "text": {
            "description": "A line of story, shown when it's revealed.",
            "type": "string",
            "minLength": 1
          },
          "effects": {
            "description": "What it does, applied automatically. Items must be in items.json.",
            "type": "array",
            "minItems": 1,
            "items": {
              "$ref": "schema.json#/definitions/effect"
            }
          },
          "notes": {
            "description": "Notes for whoever edits this. Never shown in the app.",
            "type": "string"
          }
        }
      }
    }
  }
}

content/hero.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/hero.schema.json",
  "title": "Ignis Aura hero class",
  "description": "A hero class players can pick when starting a game. See content/README.md.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "id",
    "status",
    "name",
    "description",
    "stats",
    "health",
    "resource",
    "resourceAmount"
  ],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "description": "Its id: lowercase words joined by hyphens. Other content refers to it by this.",
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "status": {
      "description": "draft while it's being worked on; ready once it's finished and checked.",
      "enum": ["draft", "ready"]
    },
    "name": {
      "description": "The class's name, e.g. 'Warrior'.",
      "type": "string",
      "minLength": 1
    },
    "description": {
      "description": "One line shown when picking a hero.",
      "type": "string",
      "minLength": 1
    },
    "stats": {
      "type": "object",
      "additionalProperties": false,
      "description": "How many d6 the hero rolls for each stat.",
      "required": ["STR", "DEX", "STL", "SUR", "ATK", "DEF", "LCK"],
      "properties": {
        "STR": {
          "description": "Strength",
          "type": "integer",
          "minimum": 0
        },
        "DEX": {
          "description": "Dexterity",
          "type": "integer",
          "minimum": 0
        },
        "STL": {
          "description": "Stealth",
          "type": "integer",
          "minimum": 0
        },
        "SUR": {
          "description": "Survival",
          "type": "integer",
          "minimum": 0
        },
        "ATK": {
          "description": "Attack",
          "type": "integer",
          "minimum": 0
        },
        "DEF": {
          "description": "Defense",
          "type": "integer",
          "minimum": 0
        },
        "LCK": {
          "description": "Luck",
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "health": {
      "description": "Starting and maximum health.",
      "type": "integer",
      "minimum": 1
    },
    "resource": {
      "description": "The class's own resource, spent on its special options and abilities.",
      "$ref": "schema.json#/definitions/resource"
    },
    "resourceAmount": {
      "description": "How much of its resource the class starts with, which is also the most it can hold.",
      "type": "integer",
      "minimum": 0
    },
    "abilities": {
      "description": "The class's special abilities, paid for from its resource.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name"],
        "properties": {
          "name": {
            "description": "The ability's name, as on the class sheet.",
            "type": "string",
            "minLength": 1
          },
          "cost": {
            "description": "How much of the resource it takes: about 10% of the pool for a strike, 25% for a guard or trick, 40% for a signature.",
            "type": "integer",
            "minimum": 0
          },
          "effect": {
            "description": "What it does at rank 1, in plain words.",
            "type": "string",
            "minLength": 1
          },
          "role": {
            "description": "The ability's job: strike (hits harder), guard (keeps someone alive), trick (bends a scene), signature (the class's big moment). Every class has one of each.",
            "enum": ["strike", "guard", "trick", "signature"]
          },
          "perRank": {
            "description": "What each rank after the first adds, in plain words, e.g. \"+3\" or \"+1 turn\".",
            "type": "string",
            "minLength": 1
          },
          "bonus": {
            "description": "Adds to the total of the hero's next roll of these stats, by the rules' bonus per rank (rules.json levels.abilities.bonusPerRank).",
            "type": "object",
            "additionalProperties": false,
            "required": ["stats"],
            "properties": {
              "stats": {
                "description": "The stats whose rolls it adds to.",
                "type": "array",
                "minItems": 1,
                "uniqueItems": true,
                "items": {
                  "enum": ["STR", "DEX", "STL", "SUR", "ATK", "DEF", "LCK"]
                }
              }
            }
          },
          "heal": {
            "description": "Heals a hero: this many six-sided dice, plus the rules' bonus per rank. target: self, or any hero.",
            "type": "object",
            "additionalProperties": false,
            "required": ["dice", "target"],
            "properties": {
              "dice": {
                "description": "How many six-sided dice of health it restores.",
                "type": "integer",
                "minimum": 1,
                "maximum": 6
              },
              "target": {
                "description": "self: only the hero using it. any: any hero, even on another tile.",
                "enum": ["self", "any"]
              }
            }
          }
        }
      }
    },
    "inventory": {
      "description": "What this hero starts with, as effects (gold, items, cards, renown).",
      "type": "array",
      "items": {
        "$ref": "schema.json#/definitions/effect"
      }
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    }
  }
}

