content/item.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/item.schema.json",
  "title": "Ignis Aura item catalog",
  "description": "Items heroes can wear, and what they do while worn, e.g. raise a stat. Items not listed here are just names in the pack.",
  "type": "object",
  "additionalProperties": false,
  "required": ["items"],
  "properties": {
    "$schema": { "type": "string" },
    "items": {
      "description": "Every item in the game: gear to wear, and things to carry.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name"],
        "properties": {
          "name": {
            "description": "Must match the name used in item effects exactly.",
            "type": "string",
            "minLength": 1
          },
          "description": {
            "description": "A line about the item, shown on its card.",
            "type": "string",
            "minLength": 1
          },
          "slot": {
            "description": "Where it's worn. twoHanded fills both hands. Heroes wear 2 necklaces, 10 rings and one of everything else. Without a slot, an item just rides in the pack.",
            "enum": [
              "head",
              "torso",
              "belt",
              "pants",
              "feet",
              "mainHand",
              "offHand",
              "twoHanded",
              "necklace",
              "ring"
            ]
          },
          "skulduggery": {
            "description": "Skulduggery it grants while worn. Every 10 Skulduggery is a free try at a lock, and any makes locks simpler to pick.",
            "type": "integer",
            "minimum": 1
          },
          "consumable": {
            "description": "Used up when it's used, like Lockpicks or a potion. Identical consumables stack: however many a hero carries, they take one pocket in the pack.",
            "type": "boolean"
          },
          "stats": {
            "description": "Added to the total of the hero's rolls for each stat while they wear it, after the dice are rolled. It doesn't add dice: only the hero's own stats do.",
            "type": "object",
            "additionalProperties": false,
            "properties": {
              "STR": {
                "description": "Adds to the total of Strength rolls while it's worn.",
                "type": "integer"
              },
              "DEX": {
                "description": "Adds to the total of Dexterity rolls while it's worn.",
                "type": "integer"
              },
              "STL": {
                "description": "Adds to the total of Stealth rolls while it's worn.",
                "type": "integer"
              },
              "SUR": {
                "description": "Adds to the total of Survival rolls while it's worn.",
                "type": "integer"
              },
              "ATK": {
                "description": "Adds to the total of Attack rolls while it's worn.",
                "type": "integer"
              },
              "DEF": {
                "description": "Adds to the total of Defence rolls while it's worn.",
                "type": "integer"
              },
              "LCK": {
                "description": "Adds to the total of Luck rolls while it's worn.",
                "type": "integer"
              }
            }
          }
        }
      }
    }
  }
}

