  "$id": "https://ignisaura.local/content/loot.schema.json",
  "title": "Ignis Aura loot pool",
  "description": "What random loot is drawn from: each item in the catalog, and how many of it the pool holds at the start of a game. Loot taken out of the pool goes to a hero; anything stolen from a hero goes back in. The Chest of Fate's rewards don't belong here.",
  "type": "object",
  "additionalProperties": false,
  "required": ["items"],
  "properties": {
    "$schema": { "type": "string" },
    "items": {
      "description": "What every game's loot pool starts with: each item and how many.",
      "type": "array",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name", "count"],
        "properties": {
          "name": {
            "description": "An item in the catalog (items.json).",
            "type": "string",
            "minLength": 1
          },
          "count": {
            "description": "How many the pool starts with: more means drawn more often.",
            "type": "integer",
            "minimum": 1,
            "maximum": 50
          }
        }
      }
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    }
  }
}

