content/quests.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/quests.schema.json",
  "title": "Ignis Aura quests",
  "description": "Side quests, started by encounters, and personal quests, chosen with a hero. The adventure's main quest is written in the adventure.",
  "type": "object",
  "additionalProperties": false,
  "required": ["status", "quests"],
  "properties": {
    "$schema": { "type": "string" },
    "status": {
      "description": "draft while it's being worked on; ready once it's finished and checked.",
      "enum": ["draft", "ready"]
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    },
    "quests": {
      "description": "Every side and personal quest.",
      "type": "array",
      "items": { "$ref": "#/definitions/quest" }
    }
  },
  "definitions": {
    "quest": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "status", "kind", "name", "description", "steps"],
      "properties": {
        "id": {
          "description": "Its id: lowercase words joined by hyphens. Encounters start, advance or fail it by this.",
          "type": "string",
          "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
        },
        "status": {
          "description": "draft while it's being worked on; ready once it's finished and checked.",
          "enum": ["draft", "ready"]
        },
        "kind": {
          "description": "side: started by an encounter's outcome (questStart effect). personal: chosen with a hero, before the game starts.",
          "enum": ["side", "personal"]
        },
        "name": {
          "description": "The quest's name, in the quest log.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What it's about, shown in the quest log.",
          "type": "string",
          "minLength": 1
        },
        "classes": {
          "description": "Personal quests: the hero classes that can choose it (their ids). Leave it out for any.",
          "type": "array",
          "items": { "type": "string", "minLength": 1 }
        },
        "start": {
          "description": "Where it starts, shown in the quest log: a location, a region or a named place.",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "location": { "$ref": "schema.json#/definitions/locationRef" },
            "region": { "description": "A region of the board, by id.", "type": "string" },
            "named": { "description": "A named place of the board, by id.", "type": "string" }
          }
        },
        "steps": {
          "description": "What must be done, in order. A step is ticked off when its hero meets its 'done' (stands somewhere, holds an item, has the gold), or when an outcome's quest effect names it.",
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "adventure.schema.json#/properties/quest/items" }
        },
        "deadline": {
          "description": "It fails if not done in time: within this many rounds of starting, or by this round.",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "rounds": {
              "description": "Rounds from when it starts.",
              "type": "integer",
              "minimum": 1
            },
            "byRound": {
              "description": "By the end of this round.",
              "type": "integer",
              "minimum": 1
            }
          }
        },
        "reward": {
          "description": "What finishing it brings: its words, and effects for whoever holds it.",
          "$ref": "schema.json#/definitions/outcome"
        },
        "failure": {
          "description": "What failing it costs (out of time, an outcome, or a personal quest's hero gone for good).",
          "$ref": "schema.json#/definitions/outcome"
        },
        "notes": {
          "description": "Notes for whoever edits this. Never shown in the app.",
          "type": "string"
        }
      }
    }
  }
}

