content/riddle.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/riddle.schema.json",
  "title": "Ignis Aura riddle pool",
  "description": "Riddles that puzzles with \"fromPool\": true draw from. See content/README.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["riddles"],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "riddles": {
      "description": "The riddles puzzles draw from when they ask from the pool.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "question", "answers", "correct"],
        "properties": {
          "id": {
            "description": "Its id: lowercase words joined by hyphens. Other content refers to it by this.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "question": {
            "description": "The riddle, as asked.",
            "type": "string",
            "minLength": 1
          },
          "answers": {
            "description": "Always 4, so a puzzle can allow up to 3 guesses.",
            "type": "array",
            "minItems": 4,
            "maxItems": 4,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "required": ["id", "label"],
              "properties": {
                "id": {
                  "description": "Its id within the riddle; 'correct' names the right one.",
                  "type": "string",
                  "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
                },
                "label": {
                  "description": "The answer as players see it.",
                  "type": "string",
                  "minLength": 1
                }
              }
            }
          },
          "correct": {
            "description": "The id of the right answer.",
            "type": "string"
          },
          "notes": {
            "description": "Notes for whoever edits this. Never shown in the app.",
            "type": "string"
          }
        }
      }
    }
  }
}

content/riddles.json:
{
  "$schema": "riddle.schema.json",
  "riddles": [
    {
      "id": "river",
      "question": "“I have a mouth but never eat, a bed but never sleep. I run, yet never walk. What am I?”",
      "answers": [
        {
          "id": "road",
          "label": "A road"
        },
        {
          "id": "river",
          "label": "A river"
        },
        {
          "id": "the-wind",
          "label": "The wind"
        },
        {
          "id": "clock",
          "label": "A clock"
        }
      ],
      "correct": "river"
    },
    {
      "id": "footsteps",
      "question": "“The more of me you take, the more you leave behind. What am I?”",
      "answers": [
        {
          "id": "footsteps",
          "label": "Footsteps"
        },
        {
          "id": "memories",
          "label": "Memories"
        },
        {
          "id": "breaths",
          "label": "Breaths"
        },
        {
          "id": "coins",
          "label": "Coins"
        }
      ],
      "correct": "footsteps"
    },
    {
      "id": "map",
      "question": "“I have cities but no houses, forests but no trees, and rivers without a single fish. What am I?”",
      "answers": [
        {
          "id": "dream",
          "label": "A dream"
