content/rules.schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/rules.schema.json",
  "title": "Ignis Aura table rules",
  "description": "Rules the app shows at the right moment during play.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "status",
    "death",
    "packSize",
    "renown",
    "levels",
    "xpRewards",
    "difficulties",
    "statCap",
    "locks",
    "resources"
  ],
  "properties": {
    "$schema": {
      "type": "string"
    },
    "status": {
      "description": "draft while it's being worked on; ready once it's finished and checked.",
      "enum": ["draft", "ready"]
    },
    "renown": {
      "description": "A hero's renown is their reputation, for good or ill. Every `step` of it earns the next title; below 0, every `step` sinks to the next title of infamy.",
      "type": "object",
      "additionalProperties": false,
      "required": ["step", "titles", "infamy"],
      "properties": {
        "step": {
          "description": "How much renown each title takes.",
          "type": "integer",
          "minimum": 1
        },
        "titles": {
          "description": "From 0 upwards: the first is for 0 to step - 1, the next for step to 2 × step - 1, and so on. The last carries on from there.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        },
        "infamy": {
          "description": "Below 0: the first is for -1 to -step, the next below that, and so on. The last carries on from there.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      }
    },
    "levels": {
      "description": "Experience: XP earns levels, up to max. xp lists the total XP each level needs, from level 2 up; past the last, each level needs as much more as the last step did. Each level brings stat points to spend on any stat, and some bring an ability pick.",
      "type": "object",
      "additionalProperties": false,
      "required": ["max", "xp", "statPoints", "bonusStatPoints", "abilities"],
      "properties": {
        "max": {
          "description": "The highest level.",
          "type": "integer",
          "minimum": 2
        },
        "xp": {
          "description": "The XP to reach each level from 2 up, in order.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "integer",
            "minimum": 1
          }
        },
        "statPoints": {
          "description": "Stat points each new level gives, to add to any stat.",
          "type": "integer",
          "minimum": 0
        },
        "bonusStatPoints": {
          "description": "Every `every`th level gives `points` stat points instead.",
          "type": "object",
          "additionalProperties": false,
          "required": ["every", "points"],
          "properties": {
            "every": {
              "description": "Every this many levels…",
              "type": "integer",
              "minimum": 2
            },
            "points": {
              "description": "…gives this many stat points instead of one.",
              "type": "integer",
              "minimum": 0
            }
          }
        },
        "abilities": {
          "description": "Ability picks: `atStart` when the hero is made, then one at level `from` and every `every` levels after. A pick learns one of the class's abilities, or ranks up one already learned, up to `ranks`. Each rank adds `bonusPerRank` to the roll's total when the ability is used.",
          "type": "object",
          "additionalProperties": false,
          "required": ["atStart", "every", "from", "ranks", "bonusPerRank"],
          "properties": {
            "atStart": {
              "description": "Ability picks a new hero starts with.",
              "type": "integer",
              "minimum": 0
            },
            "every": {
              "description": "Then a pick every this many levels…",
              "type": "integer",
              "minimum": 1
            },
            "from": {
              "description": "…starting at this level.",
              "type": "integer",
              "minimum": 2
            },
            "ranks": {
              "description": "The most ranks one ability can have.",
              "type": "integer",
              "minimum": 1
            },
            "bonusPerRank": {
              "description": "What each rank adds to an ability's bonus or healing.",
              "type": "integer",
              "minimum": 0
            }
          }
        }
      }
    },
    "locks": {
      "description": "Rune locks by tile: how many dials, how many different runes they carry (drawn at random each time, never repeated within the code) and how many tries before the lock seals.",
      "type": "object",
      "additionalProperties": false,
      "required": ["civilization", "wilderness", "dungeon", "chaos"],
      "properties": {
        "civilization": {
          "description": "Rune locks on the Civilization tile.",
          "$ref": "#/definitions/lockSize"
        },
        "wilderness": {
          "description": "Rune locks on the Wilderness tile.",
          "$ref": "#/definitions/lockSize"
        },
        "dungeon": {
          "description": "Rune locks on the Dungeon tile.",
          "$ref": "#/definitions/lockSize"
        },
        "chaos": {
          "description": "Rune locks on the Chaos tile.",
          "$ref": "#/definitions/lockSize"
        }
      }
    },
    "statCap": {
      "description": "The most any stat can be, and so the most dice a hero ever rolls for a test. Gear adds to the total, not to the stat.",
      "type": "integer",
      "minimum": 1
    },
    "difficulties": {
      "description": "The difficulty scale, easiest first: what a test's number is called. A number gets the name of the highest step at or below it, e.g. 14 is Difficult when Difficult is at 12 and Hard at 15. A hero rolls one die per stat point, so these are what the dice must reach.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["name", "at"],
        "properties": {
          "name": {
            "description": "What this step is called, e.g. 'Hard'.",
            "type": "string",
            "minLength": 1
          },
          "at": {
            "description": "The lowest roll target with this name. Quick difficulty in the creator uses it as the target.",
            "type": "integer",
            "minimum": 1
          }
        }
      }
    },
    "xpRewards": {
      "description": "The XP a hero earns for each kind of success, automatically. An outcome that gives its own xp effect earns that instead. Failures, choices and shopping earn none.",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "roll",
        "luck",
        "classOption",
        "combat",
        "challenge",
        "lockpick",
        "miniBoss",
        "boss"
      ],
      "properties": {
        "roll": {
          "description": "Passing a stat roll.",
          "type": "integer",
          "minimum": 0
        },
        "luck": {
          "description": "Winning a coin toss.",
          "type": "integer",
          "minimum": 0
        },
        "classOption": {
          "description": "Passing a class option, paid for from a class resource.",
          "type": "integer",
          "minimum": 0
        },
        "combat": {
          "description": "Winning a fight at the table, or a fight that isn't a boss.",
          "type": "integer",
          "minimum": 0
        },
        "challenge": {
          "description": "Solving a riddle, opening a rune lock, or hitting a quicktime.",
          "type": "integer",
          "minimum": 0
        },
        "lockpick": {
          "description": "Picking a lock.",
          "type": "integer",
          "minimum": 0
        },
        "miniBoss": {
          "description": "Beating a mini-boss.",
          "type": "integer",
          "minimum": 0
        },
        "boss": {
          "description": "Beating a boss.",
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "death": {
      "description": "When a hero's health reaches 0 they have fallen. Unless something saves them, their player pays goldCost or loses renownCost to be raised with full health, carries on as a class nobody else plays and that hasn't fallen this game, or lets the hero rest in peace and leaves the game.",
      "type": "object",
      "additionalProperties": false,
      "required": ["text", "goldCost", "renownCost"],
      "properties": {
        "text": {
          "description": "Shown when a hero falls.",
          "type": "string",
          "minLength": 1
        },
        "goldCost": {
          "description": "Gold it costs to be raised from the dead.",
          "type": "integer",
          "minimum": 0
        },
        "renownCost": {
          "description": "Renown it costs instead.",
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "rarities": {
      "description": "The kinds of encounter, commonest first: shown on each encounter, and how often each is drawn (odds out of their total, so 60/25/12/3 are percents). The first is for encounters that don't say.",
      "type": "array",
      "minItems": 1,
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": ["id", "name", "odds", "color"],
        "properties": {
          "id": {
            "description": "Its id: lowercase words joined by hyphens. Other content refers to it by this.",
            "type": "string",
            "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
          },
          "name": {
            "description": "What players see on the encounter's badge.",
            "type": "string",
            "minLength": 1
          },
          "odds": {
            "description": "How likely, against the others' odds added together.",
            "type": "integer",
            "minimum": 0
          },
          "color": {
            "description": "The colour of its badge, e.g. #e0a63a.",
            "type": "string",
            "pattern": "^#[0-9a-fA-F]{6}$"
          }
        }
      }
    },
    "realm": {
      "description": "The Ethereal Realm's portal, which opens just off the board's edge beside Civilization.",
      "type": "object",
      "additionalProperties": false,
      "required": ["firstRound", "openRounds", "reopenAfter", "steps"],
      "properties": {
        "firstRound": {
          "description": "It first opens on a random round between these two.",
          "type": "array",
          "minItems": 2,
          "maxItems": 2,
          "items": { "type": "integer", "minimum": 1 }
        },
        "openRounds": { "description": "Rounds it stays open.", "type": "integer", "minimum": 1 },
        "reopenAfter": {
          "description": "When it closes with no one gone through, it opens again somewhere else this many rounds later.",
          "type": "integer",
          "minimum": 1
        },
        "steps": {
          "description": "Turns the journey through the realm takes before the way out appears.",
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "keeperEvents": {
      "description": "Limits on Keeper events, unless an event sets its own: how many times each can happen a game, and how many rounds must pass between any two.",
      "type": "object",
      "additionalProperties": false,
      "required": ["perGame", "cooldownRounds"],
      "properties": {
        "perGame": {
          "description": "Times each event can happen in a game.",
          "type": "integer",
          "minimum": 1
        },
        "cooldownRounds": {
          "description": "Rounds that must pass between any two Keeper events.",
          "type": "integer",
          "minimum": 0
        }
      }
    },
    "dayNight": {
      "description": "Day and night take turns: this many rounds of day, then as many of night.",
      "type": "object",
      "additionalProperties": false,
      "required": ["roundsEach"],
      "properties": {
        "roundsEach": {
          "description": "Rounds of day, then the same of night.",
          "type": "integer",
          "minimum": 1
        }
      }
    },
    "resources": {
      "description": "Class resources (Rage, Magic, Faith...): how they come back. At the start of each of a hero's turns they regain this share of their pool, rounded (10% is about one Strike ability a turn). A rest fills the pool.",
      "type": "object",
      "additionalProperties": false,
      "required": ["regainShare"],
      "properties": {
        "regainShare": {
          "description": "The share of a hero's class resource they get back at the start of each turn (0.1 is a tenth).",
          "type": "number",
          "minimum": 0,
          "maximum": 1
        }
      }
    },
    "packSize": {
      "description": "How many items a hero can carry besides what they wear.",
      "type": "integer",
      "minimum": 1
    },
    "notes": {
      "description": "Notes for whoever edits this. Never shown in the app.",
      "type": "string"
    }
  },
  "definitions": {
    "lockSize": {
      "type": "object",
      "additionalProperties": false,
      "required": ["dials", "runes", "attempts"],
      "properties": {
        "dials": {
          "description": "How many rune dials the lock has.",
          "type": "integer",
          "minimum": 2,
          "maximum": 8
        },
        "runes": {
          "description": "At least as many as dials.",
          "type": "integer",
          "minimum": 2,
          "maximum": 24
        },
        "attempts": {
          "description": "Tries before it seals.",
          "type": "integer",
          "minimum": 1,
          "maximum": 20
        }
      }
    }
  }
}

content/schema.json:
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "$id": "https://ignisaura.local/content/schema.json",
  "title": "Ignis Aura tile",
  "description": "One board tile: its locations and the encounters that can happen at each. See content/README.md.",
  "type": "object",
  "additionalProperties": false,
  "required": ["id", "name", "icon", "locations"],
  "properties": {
    "$schema": { "type": "string" },
    "id": {
      "description": "The tile's id: lowercase words joined by hyphens.",
      "$ref": "#/definitions/slug"
    },
    "name": {
      "description": "The tile's name, as players see it.",
      "type": "string",
      "minLength": 1
    },
    "icon": { "$ref": "#/definitions/icon" },
    "closed": {
      "description": "Closed for now: shown as Coming soon, and can't be picked or stepped onto.",
      "type": "boolean"
    },
    "locations": {
      "description": "The tile's locations, each with its encounters, in the order the app lists them.",
      "type": "array",
      "minItems": 1,
      "items": { "$ref": "#/definitions/location" }
    }
  },
  "definitions": {
    "slug": {
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
    },
    "encounterId": {
      "description": "Globally unique: <tile>.<location>.<encounter>",
      "type": "string",
      "pattern": "^[a-z0-9-]+\\.[a-z0-9-]+\\.[a-z0-9-]+$"
    },
    "locationRef": {
      "description": "<tile>.<location>",
      "type": "string",
      "pattern": "^[a-z0-9-]+\\.[a-z0-9-]+$"
    },
    "icon": {
      "description": "An Ionicons name from @expo/vector-icons, or art:<name> for your own art in content/art/ (add it with the creator).",
      "type": "string",
      "minLength": 1
    },
    "stat": {
      "description": "A hero stat: Strength, Dexterity, Stealth, Survival, Attack or Defense. The hero rolls one d6 per point.",
      "enum": ["STR", "DEX", "STL", "SUR", "ATK", "DEF", "LCK"]
    },
    "check": {
      "description": "What a roll checks: a stat's dice against the difficulty (or an opposed roll, see versus), 'coin' to call and flip a coin, or 'combat' for a fight played out at the table against the enemies listed.",
      "enum": ["STR", "DEX", "STL", "SUR", "ATK", "DEF", "LCK", "coin", "combat"]
    },
    "enemy": {
      "description": "Who the hero fights, as a stat block from the encounter book.",
      "type": "object",
      "additionalProperties": false,
      "required": ["name", "stats"],
      "properties": {
        "name": {
          "description": "What players call them, e.g. 'Armored City Guards'.",
          "type": "string",
          "minLength": 1
        },
        "count": {
          "description": "How many of them. Defaults to 1.",
          "type": "integer",
          "minimum": 1
        },
        "stats": {
          "description": "In the book's order, e.g. Health 10, Dexterity 3, Attack 4, Defense 5.",
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["name", "value"],
            "properties": {
              "name": {
                "description": "The stat's name as printed in the encounter book, e.g. Health or Attack.",
                "type": "string",
                "minLength": 1
              },
              "value": { "description": "Its number.", "type": "integer" }
            }
          }
        },
        "gear": {
          "description": "Weapon or gear, e.g. 'Barehanded 1d6 + 1'.",
          "type": "string",
          "minLength": 1
        }
      }
    },
    "resource": {
      "description": "A class's own resource: a Warrior's rage, a Mage's magic, a Devout's faith, a Druid's primal, a Ranger's reflex, a Thief's skulduggery, a Bard's muse.",
      "enum": ["rage", "magic", "faith", "primal", "reflex", "skulduggery", "muse"]
    },
    "tag": {
      "description": "Labels for finding and sorting encounters (combat, magic, luck…). They never change how an encounter plays. One rule is checked: an encounter with a coin flip must be tagged luck, and only those. Add new tags to this list.",
      "enum": [
        "social",
        "financial",
        "combat",
        "exploration",
        "magic",
        "stealth",
        "shop",
        "item-shop",
        "tavern",
        "trap",
        "luck"
      ]
    },
    "tone": {
      "description": "What kind of option this is. Each theme decides how a tone looks; neutral options never get 'Doom!' or 'Triumph!'.",
      "enum": ["positive", "neutral", "negative", "special"]
    },
    "notes": {
      "description": "Author notes. Never shown in the app.",
      "type": "string"
    },
    "location": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "name", "icon", "encounters"],
      "properties": {
        "id": {
          "description": "Its id in the tile's file and in encounter ids: lowercase words joined by hyphens.",
          "$ref": "#/definitions/slug"
        },
        "name": {
          "description": "The name players see, e.g. 'City'.",
          "type": "string",
          "minLength": 1
        },
        "icon": { "$ref": "#/definitions/icon" },
        "closed": {
          "description": "Closed for now: shown as Coming soon, and its squares can't be stepped onto, whatever encounters it has.",
          "type": "boolean"
        },
        "encounters": {
          "description": "Everything that can be drawn here. Rarity, time of day and once-per-game decide which come up.",
          "type": "array",
          "items": { "$ref": "#/definitions/encounter" }
        }
      }
    },
    "encounter": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "status", "description", "actions"],
      "properties": {
        "id": { "$ref": "#/definitions/encounterId" },
        "status": {
          "description": "draft = work in progress: structure is checked, polish is not. ready = complete and fully checked.",
          "enum": ["draft", "ready"]
        },
        "title": {
          "description": "The encounter's name, shown as its heading (e.g. 'Toll Guards').",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "The scene the players read when the encounter is drawn: what the hero finds.",
          "type": "string",
          "minLength": 1
        },
        "tags": {
          "description": "Labels for finding and sorting encounters in the creator (combat, magic, luck…). Players never see them and they don't change play; an encounter with a coin flip must be tagged luck.",
          "type": "array",
          "uniqueItems": true,
          "items": { "$ref": "#/definitions/tag" }
        },
        "notes": { "$ref": "#/definitions/notes" },
        "turnedAway": { "$ref": "#/definitions/turnedAway" },
        "boss": {
          "description": "A mini-boss or a boss: shown as one, and a fight in it must award a draw from the Chest of Fate on victory.",
          "enum": ["mini", "boss"]
        },
        "rarity": {
          "description": "What kind of encounter it is, from the rarities in rules.json (common, uncommon, rare, legendary): shown to the players, and how often it's drawn against the others at its location. Leave it out for the commonest.",
          "type": "string",
          "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$"
        },
        "weight": {
          "description": "How much more often it comes up than others of its rarity at its location: 2 is twice as often. Leave it out for 1.",
          "type": "integer",
          "minimum": 1,
          "maximum": 10
        },
        "oncePerGame": {
          "description": "Once anyone succeeds at it, it leaves the draws for the rest of the game. Failing leaves it in play.",
          "type": "boolean"
        },
        "time": {
          "description": "Only drawn by day, or only by night. Leave it out for an encounter that can come at any time.",
          "enum": ["day", "night"]
        },
        "where": {
          "description": "Only drawn in these regions or named places of the board (by id). Leave it out for a general encounter, drawn anywhere at its location. Needs the digital board to know where a hero stands.",
          "type": "object",
          "additionalProperties": false,
          "properties": {
            "regions": {
              "description": "Regions it can happen in, e.g. emberlight.",
              "type": "array",
              "minItems": 1,
              "items": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" }
            },
            "named": {
              "description": "Named places it can happen at, e.g. emberlight-city.",
              "type": "array",
              "minItems": 1,
              "items": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" }
            }
          }
        },
        "hub": { "$ref": "#/definitions/hub" },
        "actions": {
          "description": "What the hero can do, in order: rolls, choices, shops, puzzles, locks, quicktimes, fights or lockpicks. Mark later steps of a scene as follow-ups. A hub has none: its destinations are the choice.",
          "type": "array",
          "minItems": 0,
          "items": { "$ref": "#/definitions/action" },
          "default": [{}]
        }
      },
      "if": { "type": "object", "properties": { "status": { "const": "ready" } } },
      "then": {
        "type": "object",
        "required": ["title", "tags"],
        "properties": {
          "tags": { "type": "array", "minItems": 1 },
          "actions": {
            "type": "array",
            "items": { "$ref": "#/definitions/readyAction" }
          }
        }
      },
      "allOf": [
        {
          "description": "Without a hub, an encounter needs at least one action.",
          "if": { "not": { "required": ["hub"] } },
          "then": { "properties": { "actions": { "minItems": 1 } } }
        }
      ]
    },
    "action": {
      "description": "What the player can do. The type decides the screen, the required data and the possible outcomes.",
      "type": "object",
      "required": ["type"],
      "properties": {
        "type": {
          "description": "What kind of action: roll, choice, shop, puzzle, lock, quicktime, fight or lockpick. It decides the screen and the fields below.",
          "enum": ["roll", "choice", "shop", "puzzle", "lock", "quicktime", "fight", "lockpick"]
        }
      },
      "allOf": [
        {
          "if": { "type": "object", "properties": { "type": { "const": "roll" } } },
          "then": { "$ref": "#/definitions/rollAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "choice" } } },
          "then": { "$ref": "#/definitions/choiceAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "shop" } } },
          "then": { "$ref": "#/definitions/shopAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "puzzle" } } },
          "then": { "$ref": "#/definitions/puzzleAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "lock" } } },
          "then": { "$ref": "#/definitions/lockAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "quicktime" } } },
          "then": { "$ref": "#/definitions/quicktimeAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "fight" } } },
          "then": { "$ref": "#/definitions/fightAction" }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "lockpick" } } },
          "then": { "$ref": "#/definitions/lockpickAction" }
        }
      ]
    },
    "rollAction": {
      "description": "Roll a stat's dice against a number, or call a coin flip. Pass or fail.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "description", "stat"],
      "properties": {
        "type": { "const": "roll" },
        "label": {
          "description": "Button heading. Defaults to the stat's (or the resource's) name.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "stat": { "$ref": "#/definitions/check" },
        "difficulty": {
          "description": "The total the dice must reach. Not used for a coin flip or a fight.",
          "type": "integer",
          "minimum": 1
        },
        "versus": {
          "description": "For an opposed roll instead of a difficulty: who rolls against the hero, e.g. \"the guards' Dexterity (3d6)\".",
          "type": "string",
          "minLength": 1
        },
        "enemies": {
          "description": "For a fight ('combat'): who the hero is up against.",
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/definitions/enemy" }
        },
        "cost": {
          "description": "A class option: what it costs from the class resource, spent whether it passes or fails. Only heroes of the class with that resource are offered it, and they need enough to try.",
          "type": "object",
          "additionalProperties": false,
          "required": ["resource", "amount"],
          "properties": {
            "resource": { "$ref": "#/definitions/resource" },
            "amount": {
              "description": "How much of the class resource it costs, spent whether it passes or fails.",
              "type": "integer",
              "minimum": 1
            }
          }
        },
        "passLabel": {
          "description": "Pass button text. Defaults to 'Pass'.",
          "type": "string",
          "minLength": 1
        },
        "failLabel": {
          "description": "Fail button text. Defaults to 'Fail'.",
          "type": "string",
          "minLength": 1
        },
        "pass": {
          "description": "What happens when the roll reaches the difficulty (or the coin comes up right).",
          "$ref": "#/definitions/outcome"
        },
        "fail": { "description": "What happens when it doesn't.", "$ref": "#/definitions/outcome" },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": { "$ref": "#/definitions/notes" },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "choiceAction": {
      "description": "The player picks one of 1-4 options, e.g. pay the toll or don't. One option is a plain step, like walking away. No dice.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description", "options"],
      "properties": {
        "type": { "const": "choice" },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "requirement": {
          "description": "Shown above the options, e.g. 'You can only pay if you have 1 gold.'",
          "type": "string",
          "minLength": 1
        },
        "options": {
          "description": "The choices the hero picks between (1–4), each with its own outcome. No dice.",
          "type": "array",
          "minItems": 1,
          "maxItems": 4,
          "items": { "$ref": "#/definitions/choiceOption" }
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": { "$ref": "#/definitions/notes" },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "choiceOption": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "label", "tone"],
      "properties": {
        "id": {
          "description": "Its id within the choice: lowercase words joined by hyphens.",
          "$ref": "#/definitions/slug"
        },
        "label": {
          "description": "The text of the choice, as the hero would say or do it.",
          "type": "string",
          "minLength": 1
        },
        "tone": { "$ref": "#/definitions/tone" },
        "title": {
          "description": "Result title. Defaults to the theme's wording for this tone.",
          "type": "string",
          "minLength": 1
        },
        "outcome": {
          "description": "What happens when the hero picks it.",
          "$ref": "#/definitions/outcome"
        }
      }
    },
    "shopAction": {
      "description": "Browse a shop: buy an item or walk away. No dice. Stock is tracked per game.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "id", "label", "description", "items"],
      "properties": {
        "type": { "const": "shop" },
        "id": {
          "description": "Unique within the encounter; identifies this shop's stock during a game.",
          "$ref": "#/definitions/slug"
        },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "items": {
          "description": "What's for sale, with prices and how many the shop has.",
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/definitions/shopItem" }
        },
        "restock": { "$ref": "#/definitions/restock" },
        "leave": {
          "description": "What happens when the player walks away without buying.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": { "$ref": "#/definitions/notes" },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "shopItem": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "name"],
      "properties": {
        "id": {
          "description": "Its id within the shop: lowercase words joined by hyphens.",
          "$ref": "#/definitions/slug"
        },
        "name": {
          "description": "The item's name, from the item catalog when it's gear the hero carries.",
          "type": "string",
          "minLength": 1
        },
        "price": {
          "description": "In gold. Buying takes this much gold automatically.",
          "type": "integer",
          "minimum": 0
        },
        "bonus": {
          "description": "Short summary shown in the shop, e.g. '+1 STR'.",
          "type": "string",
          "minLength": 1
        },
        "stock": {
          "description": "How many the shop has. Leave out for unlimited.",
          "type": "integer",
          "minimum": 1
        },
        "effects": {
          "description": "Extra effects of buying it, beyond paying and gaining the item.",
          "type": "array",
          "items": { "$ref": "#/definitions/effect" }
        }
      }
    },
    "restock": {
      "description": "When sold-out stock comes back.",
      "type": "object",
      "additionalProperties": false,
      "required": ["rule"],
      "properties": {
        "rule": {
          "description": "When the shop's stock comes back: never, every round, every few rounds, or a shuffled selection.",
          "enum": ["never", "everyRound", "everyNRounds", "shuffle"]
        },
        "every": {
          "description": "For everyNRounds: how many rounds between restocks.",
          "type": "integer",
          "minimum": 2
        },
        "display": {
          "description": "For shuffle: how many of the items are on offer at once.",
          "type": "integer",
          "minimum": 1
        }
      },
      "allOf": [
        {
          "if": { "type": "object", "properties": { "rule": { "const": "everyNRounds" } } },
          "then": { "type": "object", "required": ["every"] }
        },
        {
          "if": { "type": "object", "properties": { "rule": { "const": "shuffle" } } },
          "then": { "type": "object", "required": ["display"] }
        }
      ]
    },
    "standing": {
      "description": "The renown a hero needs to take this action, e.g. 15. Below it, the action is locked: shown, but it can't be picked.",
      "type": "object",
      "additionalProperties": false,
      "required": ["atLeast"],
      "properties": {
        "atLeast": {
          "description": "The renown the hero needs to take this action; below it, the action is locked.",
          "type": "integer"
        }
      }
    },
    "turnedAway": {
      "description": "A hero whose renown is atMost or lower is turned away before they can act, and gets this outcome instead. It uses up their turn.",
      "type": "object",
      "additionalProperties": false,
      "required": ["atMost", "outcome"],
      "properties": {
        "atMost": {
          "description": "Heroes with this much renown or less are turned away before they can act.",
          "type": "integer"
        },
        "title": {
          "description": "Result title, e.g. 'Run Out of Town'.",
          "type": "string",
          "minLength": 1
        },
        "outcome": {
          "description": "What happens to a hero who's turned away. It uses up their turn.",
          "$ref": "#/definitions/outcome"
        }
      }
    },
    "edge": {
      "description": "A head start for a hero whose stat (with items) is at least atLeast, or who is the class with this resource: a puzzle strikes out one wrong answer, a lock allows one more attempt, a quicktime's window is half as wide again.",
      "type": "object",
      "additionalProperties": false,
      "oneOf": [{ "required": ["stat", "atLeast"] }, { "required": ["resource"] }],
      "properties": {
        "stat": {
          "$ref": "#/definitions/stat"
        },
        "atLeast": {
          "description": "The stat (with items) the hero needs to get the head start.",
          "type": "integer",
          "minimum": 1
        },
        "resource": {
          "$ref": "#/definitions/resource"
        },
        "text": {
          "description": "Shown when the edge applies.",
          "type": "string",
          "minLength": 1
        }
      }
    },
    "puzzleAnswer": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "label"],
      "properties": {
        "id": {
          "description": "Its id within the puzzle; the puzzle's 'correct' names the right one.",
          "$ref": "#/definitions/slug"
        },
        "label": {
          "description": "The answer as players see it.",
          "type": "string",
          "minLength": 1
        }
      }
    },
    "puzzleAction": {
      "description": "A riddle with 2-4 answers; one is right. A wrong answer is struck out.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description"],
      "if": {
        "type": "object",
        "required": ["fromPool"],
        "properties": { "fromPool": { "const": true } }
      },
      "then": { "not": { "anyOf": [{ "required": ["answers"] }, { "required": ["correct"] }] } },
      "else": { "required": ["answers", "correct"] },
      "properties": {
        "type": {
          "const": "puzzle"
        },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "intro": {
          "description": "Who's asking, e.g. 'A voice from the stone asks'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "The riddle itself. With fromPool, the scene shown on the puzzle's button.",
          "type": "string",
          "minLength": 1
        },
        "fromPool": {
          "description": "Ask a riddle from riddles.json instead of writing one here. Leave out answers and correct.",
          "type": "boolean"
        },
        "answers": {
          "description": "The answers to choose from (2–4); one is right.",
          "type": "array",
          "minItems": 2,
          "maxItems": 4,
          "items": {
            "$ref": "#/definitions/puzzleAnswer"
          }
        },
        "correct": {
          "description": "The id of the right answer.",
          "$ref": "#/definitions/slug"
        },
        "guesses": {
          "description": "How many answers the hero may try. Defaults to 1.",
          "type": "integer",
          "minimum": 1,
          "maximum": 3
        },
        "edge": {
          "$ref": "#/definitions/edge"
        },
        "success": {
          "description": "What happens when the hero succeeds: story text, the game instruction, and its effects.",
          "$ref": "#/definitions/outcome"
        },
        "failure": {
          "description": "What happens when the hero fails.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": {
          "$ref": "#/definitions/notes"
        },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "rune": {
