        "water",
        "leaf",
        "skull",
        "eye",
        "diamond",
        "crown",
        "key",
        "feather",
        "hourglass",
        "snowflake",
        "mountain",
        "bolt",
        "anchor",
        "bell",
        "compass",
        "orbit",
        "sprout",
        "bird",
        "shell",
        "infinity"
      ]
    },
    "lockAction": {
      "description": "Turn rune dials to the right code within a few tries, reading the feedback after each. By default the lock is random every time, sized by its tile (locks in rules.json): leave out runes and code. Give both for a fixed lock with a clue.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description"],
      "properties": {
        "type": {
          "const": "lock"
        },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "clue": {
          "description": "For a fixed lock: carved near the dials, the hint that makes the code findable.",
          "type": "string",
          "minLength": 1
        },
        "runes": {
          "description": "For a fixed lock: the runes every dial cycles through, in order.",
          "type": "array",
          "minItems": 2,
          "maxItems": 12,
          "uniqueItems": true,
          "items": {
            "$ref": "#/definitions/rune"
          }
        },
        "code": {
          "description": "For a fixed lock: the opening combination, one rune per dial. Runes may repeat.",
          "type": "array",
          "minItems": 3,
          "maxItems": 8,
          "items": {
            "$ref": "#/definitions/rune"
          }
        },
        "tier": {
          "description": "Size it as a lock from this tile instead of the one it's on.",
          "enum": ["civilization", "wilderness", "dungeon", "chaos"]
        },
        "attempts": {
          "description": "Tries before it seals. Defaults to the tile's, from locks in rules.json.",
          "type": "integer",
          "minimum": 1,
          "maximum": 20
        },
        "feedback": {
          "description": "pips: right place and wrong place (Mastermind). count: only how many are in the right place. Defaults to pips.",
          "enum": ["pips", "count"]
        },
        "edge": {
          "$ref": "#/definitions/edge"
        },
        "success": {
          "description": "What happens when the hero succeeds: story text, the game instruction, and its effects.",
          "$ref": "#/definitions/outcome"
        },
        "failure": {
          "description": "What happens when the hero fails.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": {
          "$ref": "#/definitions/notes"
        },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "quicktimeAction": {
      "description": "Wait for the flame to flare, then tap in time. Tapping early fails. One try.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description"],
      "properties": {
        "type": {
          "const": "quicktime"
        },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "windowMs": {
          "description": "How long the flare lasts, in milliseconds. Defaults to 600.",
          "type": "integer",
          "minimum": 200,
          "maximum": 3000
        },
        "edge": {
          "$ref": "#/definitions/edge"
        },
        "success": {
          "description": "What happens when the hero succeeds: story text, the game instruction, and its effects.",
          "$ref": "#/definitions/outcome"
        },
        "failure": {
          "description": "What happens when the hero fails.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": {
          "$ref": "#/definitions/notes"
        },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "lockpickAction": {
      "description": "Pick a lock by tilting the phone: a steel ball rolls up a see-through clockwork lock's channel to the keyhole, past traps. Heroes with Skulduggery get a simpler lock and a free try for every 10 Skulduggery; after those, each failed try snaps one of their Lockpicks. Heroes without Skulduggery need Lockpicks to try at all.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description"],
      "properties": {
        "type": { "const": "lockpick" },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "success": {
          "description": "What happens when the hero succeeds: story text, the game instruction, and its effects.",
          "$ref": "#/definitions/outcome"
        },
        "failure": {
          "description": "What happens when the hero fails.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": { "$ref": "#/definitions/notes" },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "fightAction": {
      "description": "A fight over several exchanges. Each one the hero picks a move and rolls: a pass wounds the foe, a fail and the foe strikes back. It ends when the foe falls (victory), the hero's health runs out (defeat), or they flee.",
      "type": "object",
      "additionalProperties": false,
      "required": ["type", "label", "description", "foe", "moves"],
      "properties": {
        "type": { "const": "fight" },
        "label": {
          "description": "The button text players tap to choose it. Short, like 'Fight' or 'Pick the lock'.",
          "type": "string",
          "minLength": 1
        },
        "description": {
          "description": "What the hero is trying, in a sentence: shown under the button.",
          "type": "string",
          "minLength": 1
        },
        "foe": {
          "description": "Who the hero fights: its name, how many blows fell it, and how hard it hits. Quick difficulty sets the numbers.",
          "type": "object",
          "additionalProperties": false,
          "required": ["name", "wounds", "strike"],
          "properties": {
            "name": { "description": "What players call it.", "type": "string", "minLength": 1 },
            "wounds": {
              "description": "How many blows it takes to bring it down.",
              "type": "integer",
              "minimum": 1,
              "maximum": 8
            },
            "strike": {
              "description": "Health the hero loses each time an exchange goes against them.",
              "type": "integer",
              "minimum": 1
            }
          }
        },
        "moves": {
          "description": "The moves the hero can pick each exchange (1–4), each rolled with its own stat.",
          "type": "array",
          "minItems": 1,
          "maxItems": 4,
          "items": {
            "type": "object",
            "additionalProperties": false,
            "required": ["label", "stat", "difficulty"],
            "properties": {
              "label": {
                "description": "The move's button text, e.g. 'Slash'.",
                "type": "string",
                "minLength": 1
              },
              "stat": { "$ref": "#/definitions/stat" },
              "difficulty": {
                "description": "What the roll must reach for the move to land a blow. See the difficulty key.",
                "type": "integer",
                "minimum": 1
              },
              "description": {
                "description": "What the move is, in a few words.",
                "type": "string",
                "minLength": 1
              }
            }
          }
        },
        "victory": {
          "description": "What happens when the foe falls.",
          "$ref": "#/definitions/outcome"
        },
        "defeat": {
          "description": "What happens when the hero's health runs out.",
          "$ref": "#/definitions/outcome"
        },
        "flee": {
          "description": "Optional: lets the hero run for it between exchanges.",
          "$ref": "#/definitions/outcome"
        },
        "standing": { "$ref": "#/definitions/standing" },
        "notes": { "$ref": "#/definitions/notes" },
        "oncePerGame": { "$ref": "#/definitions/oncePerGame" },
        "followUp": { "$ref": "#/definitions/followUp" }
      }
    },
    "readyAction": {
      "description": "Extra requirements once an encounter is ready: every outcome written, every number set.",
      "type": "object",
      "allOf": [
        {
          "if": {
            "type": "object",
            "properties": {
              "type": { "const": "roll" },
              "stat": { "not": { "enum": ["coin", "combat"] } }
            },
            "not": { "required": ["versus"] }
          },
          "then": {
            "type": "object",
            "required": ["difficulty"]
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "roll" } } },
          "then": {
            "type": "object",
            "required": ["pass", "fail"],
            "properties": {
              "pass": { "$ref": "#/definitions/readyOutcome" },
              "fail": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "choice" } } },
          "then": {
            "type": "object",
            "properties": {
              "options": {
                "type": "array",
                "items": {
                  "type": "object",
                  "required": ["outcome"],
                  "properties": { "outcome": { "$ref": "#/definitions/readyOutcome" } }
                }
              }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "shop" } } },
          "then": {
            "type": "object",
            "required": ["leave"],
            "properties": {
              "leave": { "$ref": "#/definitions/readyOutcome" },
              "items": {
                "type": "array",
                "items": { "type": "object", "required": ["price"] }
              }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "puzzle" } } },
          "then": {
            "type": "object",
            "required": ["success", "failure"],
            "properties": {
              "success": { "$ref": "#/definitions/readyOutcome" },
              "failure": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "lock" } } },
          "then": {
            "type": "object",
            "required": ["success", "failure"],
            "properties": {
              "success": { "$ref": "#/definitions/readyOutcome" },
              "failure": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "fight" } } },
          "then": {
            "type": "object",
            "required": ["victory", "defeat"],
            "properties": {
              "victory": { "$ref": "#/definitions/readyOutcome" },
              "defeat": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "lockpick" } } },
          "then": {
            "type": "object",
            "required": ["success", "failure"],
            "properties": {
              "success": { "$ref": "#/definitions/readyOutcome" },
              "failure": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        },
        {
          "if": { "type": "object", "properties": { "type": { "const": "quicktime" } } },
          "then": {
            "type": "object",
            "required": ["success", "failure"],
            "properties": {
              "success": { "$ref": "#/definitions/readyOutcome" },
              "failure": { "$ref": "#/definitions/readyOutcome" }
            }
          }
        }
      ]
    },
    "outcome": {
      "type": "object",
      "additionalProperties": false,
      "properties": {
        "text": {
          "description": "Story text shown to the player.",
          "type": "string",
          "minLength": 1
        },
        "result": {
          "description": "The game instruction the players apply, in plain words.",
          "type": "string",
          "minLength": 1
        },
        "effects": {
          "description": "Machine-readable version of result, for the future character tracker. Optional.",
          "type": "array",
          "items": { "$ref": "#/definitions/effect" }
        },
        "table": {
          "description": "With effects: the rest of the result, which the players do at the table and the app doesn't track, e.g. '+1 Gear. Free Movement.' Shown after the effects.",
          "type": "string",
          "minLength": 1
        },
        "leadsTo": {
          "description": "Carries on to another action in the same encounter, by its index (0 is the first), e.g. a failed escape that ends in a fight. The turn doesn't end until that one is played out.",
          "type": "integer",
          "minimum": 0
        },
        "chances": {
          "description": "Chance outcomes: each happens with its percent chance, on top of this outcome. If they add up to less than 100, the rest is nothing extra.",
          "type": "array",
          "minItems": 1,
          "items": { "$ref": "#/definitions/chance" }
        },
        "then": {
          "description": "And then: what follows instead of the turn simply ending: send the hero to a place, on to an encounter (a hub, say), free movement by the board's rules, or nowhere. One option happens on its own; with several, the player chooses.",
          "type": "object",
          "additionalProperties": false,
          "required": ["options"],
          "properties": {
            "options": {
              "type": "array",
              "minItems": 1,
              "maxItems": 3,
              "items": { "$ref": "#/definitions/outcomeThen" }
            }
          }
        }
      }
    },
    "readyOutcome": {
      "description": "A ready outcome says what happens (result); story text is optional.",
      "type": "object",
      "required": ["result"]
    },
    "effect": {
      "type": "object",
      "required": ["type"],
      "oneOf": [
        {
          "additionalProperties": false,
          "required": ["amount"],
          "properties": {
            "type": { "const": "gold" },
            "amount": { "type": "integer" }
          }
        },
        {
          "additionalProperties": false,
          "required": ["amount"],
          "properties": {
            "type": { "const": "renown" },
            "amount": { "type": "integer" }
          }
        },
        {
          "description": "Experience points: they earn levels.",
          "additionalProperties": false,
          "required": ["amount"],
          "properties": {
            "type": { "const": "xp" },
            "amount": { "type": "integer" }
          }
        },
        {
          "additionalProperties": false,
          "required": ["name"],
          "properties": {
            "type": { "const": "item" },
            "name": { "type": "string", "minLength": 1 },
            "amount": { "type": "integer", "default": 1 }
          }
        },
        {
          "additionalProperties": false,
          "required": ["name"],
          "properties": {
            "type": { "const": "card" },
            "name": { "type": "string", "minLength": 1 }
          }
        },
        {
          "description": "Hero's next encounter happens at this location.",
          "additionalProperties": false,
          "required": ["location"],
          "properties": {
            "type": { "const": "moveTo" },
            "location": { "$ref": "#/definitions/locationRef" }
          }
        },
        {
          "description": "On the digital board, now: the hero is taken straight to a random free square of this location (e.g. a graveyard).",
          "additionalProperties": false,
          "required": ["location"],
          "properties": {
            "type": { "const": "sendTo" },
            "location": { "$ref": "#/definitions/locationRef" },
            "square": {
              "description": "Filled in by the app when it happens: where the hero landed.",
              "type": "array",
              "minItems": 2,
              "maxItems": 2,
              "items": { "type": "integer", "minimum": 0 }
            }
          }
        },
        {
          "description": "On the digital board, now: the hero is pushed this way (\"Move S 1\"), past other heroes, stopping at the board's edge or an edge that doesn't connect.",
          "additionalProperties": false,
          "required": ["direction", "squares"],
          "properties": {
            "type": { "const": "move" },
            "direction": { "enum": ["N", "NE", "E", "SE", "S", "SW", "W", "NW"] },
            "squares": { "type": "integer", "minimum": 1, "maximum": 8 }
          }
        },
        {
          "description": "On the digital board, next turn: extra squares (\"Free Movement +1\"), and/or straight to any square of a place on this tile (\"...or move to any Coin icon\": orTo is that place's id).",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "freeMovement" },
            "extra": { "type": "integer", "minimum": 0, "maximum": 6 },
            "orTo": { "type": "string", "pattern": "^[a-z0-9-]+$" }
          }
        },
        {
          "description": "A draw from the Chest of Fate, for extraordinary deeds like defeating a boss. The player draws a Fate card and enters its runes in the app.",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "fate" }
          }
        },
        {
          "description": "Loot: any amount, e.g. +3 or -2, or specific prizes with items, e.g. [\"Silver Sword\"]. Above 0 draws that many random items from the game's loot pool (content/loot.json) into the hero's pack; below 0 robs them of that many random items from their pack, never what they wear and never their hidden pocket, and those go back into the pool. The player is told exactly what was drawn or taken.",
          "additionalProperties": false,
          "anyOf": [{ "required": ["amount"] }, { "required": ["items"] }],
          "properties": {
            "type": { "const": "loot" },
            "amount": { "type": "integer", "minimum": -10, "maximum": 10, "not": { "const": 0 } },
            "items": {
              "description": "Specific prizes instead of random loot: these exact items go into the hero's loot pouch (any item, in the loot pool or not).",
              "type": "array",
              "minItems": 1,
              "items": { "type": "string", "minLength": 1 }
            }
          }
        },
        {
          "description": "The hero loses half their health, rounded in their favour (7 becomes 4), never below 1.",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "halveHealth" }
          }
        },
        {
          "description": "The hero's next turn is skipped (or that many turns).",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "loseTurn" },
            "turns": { "type": "integer", "minimum": 1, "maximum": 5 }
          }
        },
        {
          "description": "The hero gains exactly the XP to reach their next level, then spends it as usual.",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "levelUp" }
          }
        },
        {
          "description": "Completes a quest step, by its id, when it's the step it's on: the adventure's main quest, or with quest, that side or personal quest of the hero (content/quests.json).",
          "additionalProperties": false,
          "required": ["step"],
          "properties": {
            "type": { "const": "quest" },
            "step": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" },
            "quest": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" }
          }
        },
        {
          "description": "Starts a side quest for the hero (content/quests.json): it goes in their quest log.",
          "additionalProperties": false,
          "required": ["quest"],
          "properties": {
            "type": { "const": "questStart" },
            "quest": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" }
          }
        },
        {
          "description": "Fails one of the hero's quests outright, e.g. the thief got away.",
          "additionalProperties": false,
          "required": ["quest"],
          "properties": {
            "type": { "const": "questFail" },
            "quest": { "type": "string", "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$" }
          }
        },
        {
          "description": "Death outright: the hero's health drops to 0 and they have fallen.",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "slain" }
          }
        },
        {
          "description": "Hero stays put and resolves another encounter here next turn.",
          "additionalProperties": false,
          "properties": {
            "type": { "const": "stay" }
          }
        },
        {
          "description": "Raise or lower the hero's health. At 0 they are knocked out.",
          "additionalProperties": false,
          "required": ["amount"],
          "properties": {
            "type": { "const": "health" },
            "amount": { "type": "integer" }
          }
        },
        {
          "description": "Raise or lower the hero's own class resource (rage, magic, ...), between 0 and their maximum.",
          "additionalProperties": false,
          "required": ["amount"],
          "properties": {
            "type": { "const": "resource" },
            "amount": { "type": "integer" }
          }
        }
      ]
    },
    "oncePerGame": {
      "description": "Once anyone succeeds at this action, no one can take it again this game (e.g. the Wishing Well's big wish). Failing leaves it open.",
      "type": "boolean"
    },
    "chance": {
      "type": "object",
      "additionalProperties": false,
      "required": ["percent"],
      "properties": {
        "percent": {
          "description": "How often it happens, out of 100.",
          "type": "integer",
          "minimum": 1,
          "maximum": 100
        },
        "text": {
          "description": "Story text, in place of the outcome's.",
          "type": "string",
          "minLength": 1
        },
        "result": {
          "description": "The game instruction, in place of the outcome's.",
          "type": "string",
          "minLength": 1
        },
        "effects": {
          "description": "Added to the outcome's effects.",
          "type": "array",
          "items": { "$ref": "#/definitions/effect" }
        }
      }
    },
    "followUp": {
      "description": "A later step of a scene: not offered when the encounter opens, only reached when another action's outcome leads to it (leadsTo). Lets one encounter branch into a longer story with several choices and rolls.",
      "type": "boolean"
    },
    "hub": {
      "description": "A hub: a place to get your bearings and choose where to go, like a city's main square. Picking a destination doesn't end the turn: the hero plays the encounter there. Fewer random encounters, more choice.",
      "type": "object",
      "additionalProperties": false,
      "required": ["destinations"],
      "properties": {
        "prompt": {
          "description": "The question under the scene. Defaults to 'Where would you like to head to?'",
          "type": "string",
          "minLength": 1
        },
        "destinations": {
          "description": "Where the hero can head (2–8): each leads to one encounter, or to a draw from a location (all its encounters, with their rarity, time of day and places).",
          "type": "array",
          "minItems": 2,
          "maxItems": 8,
          "items": { "$ref": "#/definitions/hubDestination" }
        }
      }
    },
    "hubDestination": {
      "type": "object",
      "additionalProperties": false,
      "required": ["id", "text"],
      "properties": {
        "id": {
          "description": "Its id within the hub: lowercase words joined by hyphens.",
          "$ref": "#/definitions/slug"
        },
        "text": {
          "description": "What the hero sees, e.g. 'You see a tavern.'",
          "type": "string",
          "minLength": 1
        },
        "label": {
          "description": "A short name under it, e.g. 'The strange merchant'. Defaults to where it leads.",
          "type": "string",
          "minLength": 1
        },
        "encounter": {
          "description": "Leads to this one encounter, by its id.",
          "type": "string",
          "minLength": 1
        },
        "location": {
          "description": "Or leads to a draw from this location.",
          "$ref": "#/definitions/locationRef"
        }
      },
      "oneOf": [
        { "description": "Leads to one encounter.", "required": ["encounter"] },
        {
          "description": "Leads to a draw from a location.",
          "required": ["location"]
        }
      ]
    },
    "outcomeThen": {
      "type": "object",
      "required": ["kind"],
      "oneOf": [
        {
          "description": "Send the hero to a place: moved to a free square of it on the digital board. With play, they face an encounter there this turn.",
          "additionalProperties": false,
          "required": ["kind", "location"],
          "properties": {
            "kind": { "const": "goTo" },
            "location": { "$ref": "#/definitions/locationRef" },
            "play": {
              "description": "Face an encounter there this turn.",
              "type": "boolean"
            }
          }
        },
        {
          "description": "On to one encounter this turn, e.g. a hub like Emberlight's Main Square.",
          "additionalProperties": false,
          "required": ["kind", "encounter"],
          "properties": {
            "kind": { "const": "encounter" },
            "encounter": {
              "description": "The encounter, by id.",
              "type": "string",
              "minLength": 1
            }
          }
        },
        {
          "description": "Free movement: the next move can go further.",
          "additionalProperties": false,
          "required": ["kind"],
          "properties": {
            "kind": { "const": "freeMovement" },
            "extra": { "type": "integer", "minimum": 0, "maximum": 6 }
          }
        },
        {
          "description": "Stay where they are: the turn ends.",
          "additionalProperties": false,
          "required": ["kind"],
          "properties": { "kind": { "const": "stay" } }
        }
      ]
    }
  }
}

content/tiles/chaos.json:
{
  "$schema": "../schema.json",
  "id": "chaos",
  "name": "Chaos",
  "icon": "art:evil-tower",
  "locations": [
    {
      "id": "army-encampments",
      "name": "Army Camp",
      "icon": "art:barracks-tent",
      "encounters": [
        {
          "id": "chaos.army-encampments.draft-1",
          "status": "draft",
          "description": "A random Army encounter!",
          "actions": [
            {
              "type": "roll",
              "stat": "STR",
              "description": "Attempt to intimidate the guard.",
              "pass": {
                "text": "The guard backs down, allowing you to pass."
              },
