{
  "$schema": "../schema.json",
  "id": "civilization",
  "name": "Civilization",
  "icon": "art:castle",
  "locations": [
    {
      "id": "cities",
      "name": "City",
      "icon": "art:castle",
      "encounters": [
        {
          "id": "civilization.cities.greedy-guards",
          "status": "draft",
          "title": "Greedy Guards",
          "description": "You are stopped by a city guard demanding a toll to enter the city.",
          "tags": ["social", "financial", "luck"],
          "turnedAway": {
            "atMost": -3,
            "title": "Run Out of Town",
            "outcome": {
              "text": "The guards know your face. Before you can say a word, they drag you to the gate and throw you out, along with your dignity.",
              "result": "Move your hero to the nearest Sewers. Resolve an encounter there next turn.",
              "effects": [{ "type": "moveTo", "location": "civilization.sewers" }]
            }
          },
          "actions": [
            {
              "type": "choice",
              "label": "Pay the toll",
              "description": "Give the guard payment.",
              "requirement": "You can only pay if you have at least 1 gold.",
              "options": [
                {
                  "id": "pay",
                  "label": "Pay 1 gold",
                  "tone": "neutral",
                  "outcome": {
                    "text": "You toss a coin to the guard and go along your merry way.",
                    "result": "Lose 1 gold.",
                    "effects": [
                      {
                        "type": "gold",
                        "amount": -1
                      }
                    ]
                  }
                },
                {
                  "id": "refuse",
                  "label": "Can't/Don't Pay",
                  "tone": "neutral",
                  "outcome": {
                    "text": "The guard ushers you away from the gate.",
                    "result": "Keep hero on this Civilization tile and resolve another encounter here next turn.",
                    "effects": [
                      {
                        "type": "stay"
                      }
                    ]
                  }
                }
              ]
            },
            {
              "type": "roll",
              "stat": "STR",
              "difficulty": 12,
              "description": "Attempt to intimidate the guard.",
              "pass": {
                "text": "Head held high, you pass through the city gates. A glint in the mud nearby catchs your eye, you grab the muddy lump.",
                "result": "Gain 5 gold.",
                "effects": [
                  {
                    "type": "gold",
                    "amount": 5
                  }
                ]
              },
              "fail": {
                "text": "The guard is not impressed and calls for reinforcements. Outnumbered, you are quickly rendered unconcious. When next your eyes open you are in a graveyard.",
                "result": "Lose 5 gold. Next turn start in Civilization - Graveyard.",
                "effects": [
                  {
                    "type": "gold",
                    "amount": -5
                  },
                  {
                    "type": "moveTo",
                    "location": "civilization.graveyards"
                  }
                ]
              }
            },
            {
              "type": "roll",
              "stat": "coin",
              "cost": { "resource": "magic", "amount": 5 },
              "description": "Cast a spell to make yourself invisible.",
              "pass": {
                "text": "With a quiet utterance and a flick of your wrist, you disapear! You waltz through the gates unseen leaving the guard dumbfounded.",
                "result": "Place your hero on any Civilization tile you like, resolve an encounter there next turn."
              },
              "fail": {
                "text": "When you meant to utter a 'Uah' sound you accidently utter 'Oolah', as you flick your wrist to exectute the spell, a pitiful spark is expelled instead. Feeling defeated you go to hand the guard some gold.",
                "result": "Lose 5 gold. If you have no gold, place your hero on a Prison tile and resolve an encounter there next turn."
              },
              "notes": "No effects yet: the fail result is conditional and there is no Prison location in the data."
            },
            {
              "type": "roll",
              "stat": "DEX",
              "difficulty": 16,
              "description": "Attempt to distract the guard and slip past.",
              "pass": {
                "text": "Hand hidden under your cloak, you flick a sound maker, unseen, behind the guard.Your ruse works. Guard distracted you slip past him into the crowd. You manage to pilfer a few coins along the way.",
                "result": "Gain 8 gold.",
                "effects": [
                  {
                    "type": "gold",
                    "amount": 8
                  }
                ]
              },
              "fail": {
                "text": "As you attempt to sneakily flick one of your standard issue sound makers to cause a distraction, the guard spots the attempt. He and his fellow guards quickly grab and haul you away.",
                "result": "Lose 4 gold. Place your hero on a Prison tile, resolve an encounter there your next turn."
              },
              "notes": "Fail has no effects yet: there is no Prison location in the data."
            },
            {
              "type": "roll",
              "stat": "coin",
              "description": "Attempt to persuade the guard to let you in.",
              "pass": {
                "text": "While being equal parts wiley and complimentary, you manage to boost the guards ego and he just waves you through.",
                "result": "Place your hero on any Civilization tile in range and resolve an encounter there next turn."
              },
              "fail": {
                "text": "As you blubber and stumble over your intended words you fail to make your case. The guard grimaces at you and holds out his hand for payment.",
                "result": "Lose 1 gold.",
                "effects": [
                  {
                    "type": "gold",
                    "amount": -1
                  }
                ]
              }
            }
          ],
          "notes": "Draft: it overlaps with Andrew's The Toll Guards. Andrew will rework it into a different guard encounter."
        },
        {
          "id": "civilization.cities.the-toll-guards",
          "status": "ready",
          "title": "For Whom The Guards Toll",
          "description": "As you walk beneath the tall, glittering, amber-hued stone archway of the gates of the city of Emberlight, a pair of heavily armored guards signal you to stop. One of the guards eyeballs you while gripping the pommel of his great hammer tightly. He shoves his hand against your chest, stopping you in place. \n\n“20 gold to pass, stranger, or you can piss off back to where you came from.” The reek of ale and sweat accosts your nostrils.",
          "tags": ["social", "financial", "combat", "luck"],
          "notes": "From Andrew's Encounters Book (City). Board movement is left to the table; gear is loot, given by the app (Andrew, 2026-10-23).",
          "actions": [
            {
              "type": "roll",
              "label": "Renown",
              "stat": "coin",
              "standing": { "atLeast": 15 },
              "description": "If you have 15 or more renown, you may stare down the guards hoping that they recognize you and leave you be. Call and flip a coin.",
              "pass": {
                "text": "Suddenly recognizing you they profusely apologize and return to their posts after giving you an item from their lost and found crate as an apology and a promise to not tell the commander of the guard of their behavior.",
                "result": "+1 loot. Free Movement.",
                "effects": [{ "type": "loot", "amount": 1 }]
              },
              "fail": {
                "text": "They growl as they roughly shove you outside the city.",
                "result": "Move South 1 space.",
                "effects": [{ "type": "move", "direction": "S", "squares": 1 }]
              }
            },
            {
              "type": "choice",
              "label": "Pay",
              "description": "Pay the toll.",
              "options": [
                {
                  "id": "pay",
                  "label": "Pay",
                  "tone": "neutral",
                  "outcome": {
                    "result": "-5 gold. Free Movement +1",
                    "effects": [
                      { "type": "gold", "amount": -5 },
                      { "type": "freeMovement", "extra": 1 }
                    ],
                    "table": "Free Movement +1",
                    "text": "You hand over a handful of gold as requested. The guards laugh in your face as they walk back to their posts allowing you entry. "
                  }
                }
              ],
              "requirement": "You can only pay if you have 5 gold."
            },
            {
              "type": "roll",
              "label": "Fight",
              "stat": "combat",
              "description": "You may attempt to fight the guards. ",
              "enemies": [
                {
                  "name": "Drunk Armored City Guards",
                  "count": 2,
                  "stats": [
                    { "name": "Health", "value": 10 },
                    { "name": "Dexterity", "value": 3 },
                    { "name": "Attack", "value": 4 },
                    { "name": "Defense", "value": 5 },
                    { "name": "Perception", "value": 2 }
                  ]
                }
              ],
              "pass": {
                "result": "+1 loot, +5 gold, Free Movement.",
                "effects": [
                  {
                    "type": "gold",
                    "amount": 5
                  },
                  { "type": "loot", "amount": 1 },
                  { "amount": 1, "type": "renown" }
                ],
                "table": "Free Movement.",
                "text": "As you stand over the guards writing in pain on the ground and very large woman in glistening rose gold armor strides over. \"Citizen, on behalf of the city of Emberlight I apologize for these fools behavior. As the Commander of the Watch, I assure you they will be....retrained. Please accept my apologies and welcome to the city of Emberlight.\"\n\nShe hands you a few coins and ushers you along as other guards appear to haul the drunks away."
              },
              "fail": {
                "text": "You awaken quite bruised and battered in a cell. Your pack feels lighter. This can't bode well. ",
                "result": "You lose a turn. Minus half health. -10 gold. -1 loot. - Renown. You have been imprisoned. ",
                "effects": [
                  {
                    "type": "gold",
                    "amount": -10
                  },
                  { "type": "loseTurn" },
                  { "type": "halveHealth" },
                  { "type": "loot", "amount": -1 },
                  { "amount": -1, "type": "renown" }
                ],
                "table": "Do not move your character from the city tile this turn."
              },
              "notes": "Losing the turn and half the health are applied by the app (Andrew, 2026-10-23: \"you lose half your HP\").",
              "passLabel": "Victory",
              "failLabel": "Defeat"
            },
            {
              "type": "roll",
              "label": "Run",
              "stat": "DEX",
              "versus": "the guards' Dexterity (3d6)",
              "description": "Roll your Dexterity VS the guards’ Dexterity roll (3d6).",
              "pass": {
                "text": "You quickly dash off into the crowd, past the guards into the city.",
                "result": "+1 renown, Free Movement +1",
                "effects": [
                  { "type": "renown", "amount": 1 },
                  { "type": "freeMovement", "extra": 1 }
                ],
                "table": "Free Movement +1"
              },
              "fail": {
                "text": "The guards beat you, rob you and toss you out of the city.",
                "result": "-5 health, -2 gold, Move 2 SE.",
                "effects": [
                  { "type": "health", "amount": -5 },
                  { "type": "gold", "amount": -2 }
                ],
                "table": "Move 2 SE."
              }
            },
            {
              "type": "roll",
              "label": "Stealth",
              "stat": "STL",
              "versus": "the guards' Perception (2d6)",
              "description": "You may roll your Stealth VS the guards’ Perception roll (2d6).",
              "pass": {
                "text": "You quickly dive and roll under a passing cart, jolt yourself upright and deftly hide amongst the crowd and gain entrance to the city.",
                "result": "+2 renown, Free Movement +1.",
                "effects": [
                  { "type": "renown", "amount": 2 },
                  { "type": "freeMovement", "extra": 1 }
                ],
                "table": "Free Movement +1."
              },
              "fail": {
                "text": "As you attempt to take flight, the guards anticipate your move and grab you by the shoulders and throw you to the ground. They beat you, rob you and toss you out of the city.",
                "result": "-5 health, -2 gold, Move 2 NE.",
                "effects": [
                  { "type": "health", "amount": -5 },
                  { "type": "gold", "amount": -2 }
                ],
                "table": "Move 2 NE."
              }
            }
          ],
          "oncePerGame": true,
          "time": "day",
          "where": { "regions": ["emberlight"], "named": ["emberlight-city"] }
        },
        {
          "id": "civilization.cities.sounds-in-the-dark",
          "status": "ready",
          "title": "Sounds In The Dark",
          "description": "As you walk through the cobblestone streets of the city, the sun begins to set. As the shadows lengthen you hear a commotion in a nearby alley. Do you investigate?\n\nIf you do: as you walk into the dark alley, the sounds that alerted you become more clear. You hear a blade pulled from its scabbard. Your eyes slowly adjust to the low light and you see two rough looking folks threatening a young crying woman. She clutches a basket close to her chest. Noticing the echoing sounds of your footfalls the two ruffians turn towards you. “This isn’t your business, stranger. Turn about or I’ll stick ya between ya ribs. Fuck off!”",
          "tags": ["combat", "social", "stealth", "luck"],
          "notes": "From Andrew's Encounters Book (City). Board movement is left to the table; gear is loot, given by the app (Andrew, 2026-10-23).",
          "actions": [
            {
              "type": "choice",
              "label": "No",
              "description": "Don't get involved.",
              "options": [
                {
                  "id": "leave",
                  "label": "No",
                  "tone": "neutral",
                  "outcome": {
                    "text": "Deciding to not interfere in business that is not yours you move on.",
                    "result": "Free Movement."
                  }
                }
              ]
            },
            {
              "type": "roll",
              "label": "Fight",
              "stat": "combat",
              "description": "Fight the ruffians.",
              "enemies": [
                {
                  "name": "Dirty Ruffians",
                  "count": 2,
                  "stats": [
                    { "name": "Health", "value": 8 },
                    { "name": "Dexterity", "value": 5 },
                    { "name": "Attack", "value": 2 },
                    { "name": "Defense", "value": 3 },
                    { "name": "Perception", "value": 2 }
                  ]
                }
              ],
              "pass": {
                "text": "Standing over the dead, you nod at the woman as she gives you a thankful nod back and runs off in the opposite direction. You search the corpses, taking what you can as quickly as you can and leave the alley.",
                "result": "+10 gold, +4 renown, +2 loot, Free Movement.",
                "effects": [
                  { "type": "gold", "amount": 10 },
                  { "type": "renown", "amount": 4 },
                  { "type": "loot", "amount": 2 }
                ],
                "table": "Free Movement."
              },
              "fail": {
                "text": "Bloodied and prone you look up at the stars unable to move, struggling to breathe. A dark silhouette stands over you, the last thing you see is a large glistening dagger descending towards your one un-swollen eye. You feel nothing ever again.",
                "result": "You are dead.",
                "effects": [{ "type": "slain" }]
              }
            },
            {
              "type": "roll",
              "label": "Run",
              "stat": "DEX",
              "versus": "the ruffians' Dexterity",
              "description": "Roll your Dexterity VS the ruffians’ Dexterity.",
              "pass": {
                "text": "Realizing you are a coward, you turn tail and run. You trip as you round the corner onto the main street. Horrified and frightened you stagger back to your feet and run into the city night.",
                "result": "-8 renown, -2 gold.",
                "effects": [
                  { "type": "renown", "amount": -8 },
                  { "type": "gold", "amount": -2 }
                ]
              },
              "fail": {
                "result": "You enter combat. Go to the Fight option to resolve the encounter.",
                "leadsTo": 1
              }
            },
            {
              "type": "roll",
              "label": "Stealth",
              "stat": "STL",
              "versus": "the ruffians' Perception",
              "description": "Roll your Stealth VS the ruffians’ Perception.",
              "pass": {
                "text": "You quickly disappear into the shadows like a wraith. Emerging from behind them, you swiftly slam their heads together knocking them out cold. The young lady profusely thanks you, reaches into her basket handing you something before running out of the alley. You quickly make yourself scarce.",
                "result": "+1 loot. +2 gold. +4 renown.",
                "effects": [
                  { "type": "gold", "amount": 2 },
                  { "type": "renown", "amount": 4 },
                  { "type": "loot", "amount": 1 }
                ]
