// The rules, as the How to play screen shows them: one section per topic, each a list of
// entries with an icon. Add a section here and it appears in the list.
//
// Written for players at the table, from Andrew's design docs and what the app does today.

import { rules } from "./heroes";
import type { ResourceKey, StatKey } from "./types";

/** Where an entry's icon comes from: a stat's, a class resource's, or any icon by name. */
export type RuleIcon = { stat: StatKey } | { resource: ResourceKey } | { name: string };

export interface RuleEntry {
  title: string;
  icon: RuleIcon;
  /** Paragraphs. */
  text: string[];
}

export interface RuleSection {
  id: string;
  title: string;
  /** One line under the title in the list. */
  summary: string;
  icon: string;
  /** Shown above the entries. */
  intro: string[];
  entries: RuleEntry[];
}

/** 5 → "5th". */
function ordinal(n: number): string {
  const tens = n % 100;
  if (tens >= 11 && tens <= 13) return `${n}th`;
  return `${n}${({ 1: "st", 2: "nd", 3: "rd" } as Record<number, string>)[n % 10] ?? "th"}`;
}

