            " to the roll when you use it, and using one costs your class's resource. When there's something to spend, Level up appears on your hero sheet.",
        ],
      },
      {
        title: "Renown",
        icon: { name: "ribbon" },
        text: [
          "Your reputation: how well known your deeds are, for good or ill. Every hero starts at 0, and it can go below. Every 50 earns a new title, from Known to Legendary; sink below 0 and you'll be Disreputable, then Infamous.",
          "Some encounters only open up to heroes with enough renown, and some turn away heroes with too little.",
        ],
      },
      {
        title: "Gold",
        icon: { name: "logo-bitcoin" },
        text: [
          "What you spend in shops and on bribes, tolls and wishes. Anything that costs more gold than you have is greyed out.",
        ],
      },
    ],
  },
];

export function getRuleSection(id: string): RuleSection | undefined {
  return RULE_SECTIONS.find((section) => section.id === id);
}

