src/content/types.ts:
// Types for the game content in content/tiles/*.json.
// These mirror content/schema.json: the schema validates the files, these types describe them to the app.
// Keep the two in step when the content format changes.

/** The seven stats a hero rolls dice for: one d6 per point. */
export type StatKey = "STR" | "DEX" | "STL" | "SUR" | "ATK" | "DEF" | "LCK";

export const STAT_KEYS: StatKey[] = ["STR", "DEX", "STL", "SUR", "ATK", "DEF", "LCK"];

/**
 * What a roll checks: a stat's dice against a number, calling a coin flip, or a fight played
 * out at the table (initiative, attack against defense) that the hero wins or loses.
 */
export type Check = StatKey | "coin" | "combat";

/**
 * Each class's own pool of power, spent on its special options and abilities: a Warrior's
 * Rage, a Mage's Magic, and so on. Options that cost one are only offered to that class.
 */
export type ResourceKey = "rage" | "magic" | "faith" | "primal" | "reflex" | "skulduggery" | "muse";

/** What an option costs from the class resource, spent whether it passes or fails. */
export interface ResourceCost {
  resource: ResourceKey;
  amount: number;
}

/** What an encounter is about. Classification only. Keep in step with "tag" in the schema. */
export type Tag =
  | "social"
  | "financial"
  | "combat"
  | "exploration"
  | "magic"
  | "stealth"
  | "shop"
  | "item-shop"
  | "tavern"
  | "trap"
  /** Has a coin-toss check (a roll with "stat": "coin"): decided by a coin, real or digital. */
  | "luck";

/** What kind of option this is; each theme decides how a tone looks. */
export type Tone = "positive" | "neutral" | "negative" | "special";

/** A compass direction, as encounters write them: "Move NE 1". */
export type CompassDirection = "N" | "NE" | "E" | "SE" | "S" | "SW" | "W" | "NW";

export type Effect =
  | { type: "gold"; amount: number }
  | { type: "renown"; amount: number }
  /** Experience: earns levels. */
  | { type: "xp"; amount: number }
  | { type: "item"; name: string; amount?: number }
  | { type: "card"; name: string }
  | { type: "moveTo"; location: string }
  | { type: "stay" }
  /**
   * On the digital board, now: pushed this way ("Move S 1"), stopping at the
   * board's edge or an edge that doesn't connect.
   */
  | { type: "move"; direction: CompassDirection; squares: number }
  /**
   * On the digital board, next turn: `extra` more squares ("Free Movement +1"), and/or straight
   * to any square of a place on this tile ("…or move to any Coin icon": `orTo` is its id).
   */
  | { type: "freeMovement"; extra?: number; orTo?: string }
  | { type: "health"; amount: number }
  /** Spends or restores the hero's own class resource (Rage, Magic, ...). */
  | { type: "resource"; amount: number }
  /** A draw from the Chest of Fate: for extraordinary deeds, like defeating a boss. */
  | { type: "fate" }
  /** Death outright: health to 0, whatever it was. */
  | { type: "slain" }
  /**
   * Completes a quest's step, by its id (when it's the next one): the adventure's main quest, or
   * with `quest`, that side or personal quest of the hero.
   */
  | { type: "quest"; step: string; quest?: string }
  /** Starts a side quest (content/quests.json) for the hero: it goes in their quest log. */
  | { type: "questStart"; quest: string }
  /** Fails one of the hero's quests outright (e.g. the thief got away). */
  | { type: "questFail"; quest: string }
  /** The hero loses half their health (rounded in their favour), never below 1. */
  | { type: "halveHealth" }
  /** The hero's next turn (or turns) is skipped. */
  | { type: "loseTurn"; turns?: number }
  /** The hero gains exactly the XP to reach their next level. */
  | { type: "levelUp" }
  /**
   * Loot. With `items` in the content: those exact prizes. Otherwise random loot from the game's
   * pool (amount above 0), or robbed of random items from the pack (below 0): never what's worn,
   * never the hidden pocket. For random loot, `items` is filled in when the outcome is recorded:
   * what was actually drawn or taken. Prizes and draws go into the loot pouch, to be opened.
   */
  | { type: "loot"; amount?: number; items?: string[] }
  /**
   * Gains a trait (content/traits.json), or cures it with `cure`. Curing a trait that can't be
   * cured does nothing. Not offered in the content schema yet: traits aren't in the app.
   */
  | { type: "trait"; id: string; cure?: boolean }
  /**
   * On the digital board, now: taken straight to a random free square of this location
   * ("tileId.locationId"). `square` is filled in when it's recorded: where they landed.
   */
  | { type: "sendTo"; location: string; square?: [number, number] }
  /** In the Ethereal Realm: the hero finds the way out, back to the square they entered from. */
  | { type: "leaveRealm" };

export interface Outcome {
  /** Story text shown to the player. */
  text?: string;
  /** The game instruction the players apply, in plain words. */
  result?: string;
  /** Machine-readable version of `result`, for the future character tracker. */
  effects?: Effect[];
  /**
   * With effects: the rest of the result, which the players do at the table and the app doesn't
   * track, e.g. "+1 Gear. Free Movement."
   */
  table?: string;
  /**
   * Carries on to another action in the same encounter (its index), e.g. a failed escape that
   * ends in a fight. The turn doesn't end until that one is played out.
   */
  leadsTo?: number;
  /** Chance outcomes: each happens with its percent chance, on top of this outcome. */
  chances?: Chance[];
  /**
   * And then: what follows instead of the turn simply ending. One option happens; several,
   * and the player chooses between them.
   */
  then?: { options: OutcomeThen[] };
}

/**
 * What can follow an outcome: going to a place (moved there on the board, and with `play`, an
 * encounter there this turn), going on to one encounter this turn (a hub, say), a freer move by
 * the board's rules, or staying put.
 */
export type OutcomeThen =
  | { kind: "goTo"; location: string; play?: boolean }
  | { kind: "encounter"; encounter: string }
  | { kind: "freeMovement"; extra?: number }
  | { kind: "stay" };

/** A chance outcome: what happens on top, `percent` times in a hundred. */
export interface Chance {
  percent: number;
  /** In place of the outcome's story text. */
  text?: string;
  /** In place of the outcome's game instruction. */
  result?: string;
  /** Added to the outcome's effects. */
  effects?: Effect[];
}

/** Who the hero is up against in a fight at the table: a stat block from the encounter book. */
export interface Enemy {
  name: string;
  /** How many of them. Defaults to 1. */
  count?: number;
  /** Their stats, in the book's order, e.g. Health 10, Dexterity 3, Attack 4. */
  stats: { name: string; value: number }[];
  /** Weapon or gear, e.g. "Barehanded 1d6 + 1". */
  gear?: string;
}

/** The renown a hero needs to take an action. Below it, the action is locked. */
export interface StandingNeeded {
  atLeast: number;
}

/** Turns away a hero whose renown is this low, before they can do anything else. */
export interface TurnedAway {
  atMost: number;
  /** Result title, e.g. "Run Out of Town". */
  title?: string;
  outcome: Outcome;
}

/** Roll a stat's dice against a number, or call a coin flip. Pass or fail. */
export interface RollAction {
  type: "roll";
  label?: string;
  description: string;
  stat: Check;
  /** The total the dice must reach. Not used for a coin flip or a fight. */
  difficulty?: number;
  /** For an opposed roll instead of a difficulty: who rolls against the hero, and how. */
  versus?: string;
  /** For a fight: who the hero is up against. */
  enemies?: Enemy[];
  /**
   * A class option: what it costs from the class resource, spent whether it passes or fails.
   * Only heroes of the class with that resource are offered it.
   */
  cost?: ResourceCost;
  passLabel?: string;
  failLabel?: string;
  pass?: Outcome;
  fail?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

export interface ChoiceOption {
  id: string;
  label: string;
  tone: Tone;
  /** Result title; defaults to the theme's wording for the tone. */
  title?: string;
  outcome?: Outcome;
}

/** Pick one of 1–4 options (one is a plain step, like walking away). No dice. */
export interface ChoiceAction {
  type: "choice";
  label: string;
  description: string;
  requirement?: string;
  options: ChoiceOption[];
  standing?: StandingNeeded;
  notes?: string;
}

export interface ShopItem {
  id: string;
  name: string;
  price?: number;
  bonus?: string;
  /** How many the shop has; undefined means unlimited. */
  stock?: number;
  effects?: Effect[];
}

export type RestockRule =
  | { rule: "never" }
  | { rule: "everyRound" }
  | { rule: "everyNRounds"; every: number }
  | { rule: "shuffle"; display: number };

/** Buy an item or walk away. No dice. */
export interface ShopAction {
  type: "shop";
  /** Unique within the encounter; identifies this shop's stock during a game. */
  id: string;
  label: string;
  description: string;
  items: ShopItem[];
  restock?: RestockRule;
  leave?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

/**
 * A head start for a hero whose stat (with items) is at least `atLeast`: a puzzle strikes out
 * one wrong answer, a lock allows one more attempt, a quicktime's window is half as wide again.
 */
export interface Edge {
  /** A stat (with items) of at least `atLeast`... */
  stat?: StatKey;
  atLeast?: number;
  /** ...or being a class with this resource, e.g. a Mage's magic. */
  resource?: ResourceKey;
  /** Shown when the edge applies, e.g. "Your arcane sight dims one wrong answer." */
  text?: string;
}

export interface PuzzleAnswer {
  id: string;
  label: string;
}

/** A riddle with 2–4 answers. One is right. Its own, or drawn from the riddle pool. */
export interface PuzzleAction {
  type: "puzzle";
  label: string;
  /** Who's asking, e.g. "A voice from the stone asks". */
  intro?: string;
  /** The riddle itself; for a puzzle from the pool, the scene shown on its button. */
  description: string;
  /** Ask a riddle from content/riddles.json instead of its own answers. */
  fromPool?: boolean;
  /** Required unless fromPool. */
  answers?: PuzzleAnswer[];
  /** The id of the right answer. Required unless fromPool. */
  correct?: string;
  /** How many answers the hero may try; a wrong one is struck out. Defaults to 1. */
  guesses?: number;
  edge?: Edge;
  success?: Outcome;
  failure?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

/** A card in the physical Chest of Fate. Mirrors content/fate.schema.json. */
export interface FateCard {
  id: string;
  /** The four runes on its face, left to right. */
  runes: Rune[];
  name: string;
  rarity: "common" | "uncommon" | "rare" | "legendary";
  /** A line of story, shown when it's revealed. */
  text: string;
  /** What it does, applied automatically. */
  effects: Effect[];
  notes?: string;
}

/** One riddle in the pool. Mirrors content/riddle.schema.json. */
export interface Riddle {
  id: string;
  question: string;
  answers: PuzzleAnswer[];
  correct: string;
  notes?: string;
}

/** The symbols a lock's dials can show. Each theme draws them in its own runic glow. */
export type Rune =
  | "sun"
  | "moon"
  | "star"
  | "flame"
  | "water"
  | "leaf"
  | "skull"
  | "eye"
  | "diamond"
  | "crown"
  | "key"
  | "feather"
  | "hourglass"
  | "snowflake"
  | "mountain"
  | "bolt"
  | "anchor"
  | "bell"
  | "compass"
  | "orbit"
  | "sprout"
  | "bird"
  | "shell"
  | "infinity";

/** The four tiles, easiest first: a lock's size depends on which it's on. */
export type LockTier = "civilization" | "wilderness" | "dungeon" | "chaos";

/**
 * Turn rune dials to the right code within a few tries. Random every time, sized by its tile,
 * unless runes and code are given: then it's a fixed lock, with a clue.
 */
export interface LockAction {
  type: "lock";
  label: string;
  description: string;
  /** For a fixed lock: carved near the dials, the hint that makes the code findable. */
  clue?: string;
  /** For a fixed lock: the runes every dial cycles through, in order. */
  runes?: Rune[];
  /** For a fixed lock: the opening combination, one rune per dial. Runes may repeat. */
  code?: Rune[];
  /** Size it as a lock from this tile instead of the one it's on. */
  tier?: LockTier;
  /** Tries before it seals. Defaults to the tile's. */
  attempts?: number;
  /** pips: right place and wrong place (Mastermind); count: only how many are in the right place. */
  feedback?: "pips" | "count";
  edge?: Edge;
  success?: Outcome;
  failure?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

/** Wait for the flame to flare, then tap in time. Tapping early fails. */
export interface QuicktimeAction {
  type: "quicktime";
  label: string;
  description: string;
  /** How long the flare lasts, in milliseconds. Defaults to 600. */
  windowMs?: number;
  edge?: Edge;
  success?: Outcome;
  failure?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

/** One way to attack a foe: a roll against a stat. */
export interface FightMove {
  label: string;
  stat: StatKey;
  difficulty: number;
  description?: string;
}

/** Who the hero is fighting. */
export interface Foe {
  name: string;
  /** How many blows it takes to bring it down. */
  wounds: number;
  /** Health the hero loses each time an exchange goes against them. */
  strike: number;
}

/**
 * A fight over several exchanges: each one the hero picks a move and rolls. A pass wounds the
 * foe; a fail and the foe strikes back. It ends when the foe falls, the hero does, or they flee.
 */
export interface FightAction {
  type: "fight";
  label: string;
  description: string;
  foe: Foe;
  /** 1–4 ways to attack. */
  moves: FightMove[];
  victory?: Outcome;
  /** When the hero's health runs out. */
  defeat?: Outcome;
  /** Lets the hero run for it between exchanges. */
  flee?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

/**
 * Pick a lock by tilting the phone: a steel ball rolls up the lock's channel to the keyhole,
 * past traps. Skulduggery earns free tries and a simpler lock; after that, Lockpicks.
 */
export interface LockpickAction {
  type: "lockpick";
  label: string;
  description: string;
  success?: Outcome;
  failure?: Outcome;
  standing?: StandingNeeded;
  notes?: string;
}

export type Action = (
  | LockpickAction
  | RollAction
  | ChoiceAction
  | ShopAction
  | PuzzleAction
  | LockAction
  | QuicktimeAction
  | FightAction
) & {
  /** Once anyone succeeds at it, no one can take it again this game. */
  oncePerGame?: boolean;
  /** A later step of a scene: only reached when an outcome leads to it, not offered at first. */
  followUp?: boolean;
};
export type ActionType = Action["type"];

export interface Encounter {
  id: string;
  status: "draft" | "ready";
  title?: string;
  description: string;
  tags?: Tag[];
  notes?: string;
  turnedAway?: TurnedAway;
  /** A mini-boss or a boss: shown as one, and its victory must earn a draw from the Chest of Fate. */
  boss?: "mini" | "boss";
  /** Its rarity's id (rules.json): shown on it, and how often it's drawn. Unset: the commonest. */
  rarity?: string;
  /** Once anyone succeeds at it, it leaves the draws for the rest of the game. */
  oncePerGame?: boolean;
  /** How many times as often as others of its rarity at its location. Unset: 1. */
  weight?: number;
  /** A hub: the hero chooses where to go instead of taking an action (actions is then empty). */
  hub?: Hub;
  /** Only drawn by day, or only by night. Unset: drawn at any time. */
  time?: TimeOfDay;
  /**
   * Only drawn in these regions or named places (by id, from the board). Unset: a general
   * encounter, drawn anywhere at its location.
   */
  where?: { regions?: string[]; named?: string[] };
  actions: Action[];
}

export interface Location {
  id: string;
  name: string;
  /** An Ionicons name. */
  icon: string;
  /** Closed for now: Coming soon, and its squares can't be stepped onto. */
  closed?: boolean;
  encounters: Encounter[];
}

export interface Tile {
  id: string;
  name: string;
  /** An Ionicons name. */
  icon: string;
  /** Closed for now: Coming soon, and can't be picked or stepped onto. */
  closed?: boolean;
  locations: Location[];
}

/** One tile's place on the digital board, and the location on each of its squares. */
export interface BoardTile {
  tileId: string;
  /** Its top-left square on the whole board, as [x, y]. */
  origin: [number, number];
  /** Row by row from the top: location ids on this tile. */
  squares: string[][];
}

/** The digital board (content/board.json). */
export interface BoardLayout {
  /** Squares across (and down) each tile. */
  size: number;
  /** Tile ids in the order heroes travel them; each connects only to its neighbours here. */
  journey: string[];
  /** Where heroes start, in turn order, as [x, y]. */
  start: [number, number][];
  tiles: BoardTile[];
  /** Regions: groups of nearby squares, like Emberlight's city, sewers and graveyard. */
  regions?: BoardRegion[];
  /** Named places: single squares with a name of their own, like the City of Emberlight. */
  named?: NamedSquare[];
  /** Squares closed for now, as [x, y]: locked, and no hero can step onto them. */
  closed?: [number, number][];
}

/** A region of the board: squares near each other, touching, under one name. */
export interface BoardRegion {
  id: string;
  name: string;
  squares: [number, number][];
}

/** One square with a name of its own. */
export interface NamedSquare {
  id: string;
  name: string;
  square: [number, number];
}

/** Who an adventure is written for. */
export type AdventureParty = "solo" | "group" | "any";

/** How an adventure sets up the game. Everything is optional. */
export interface AdventureSetup {
  /** The suggested game mode; players can still change it. */
  mode?: { id: string; rounds?: number };
  /** Where every hero's piece starts: "<tile>.<location>". */
  start?: { location: string; note?: string };
  /** What each hero starts with. */
  inventory?: Effect[];
  /** Special rules for the first round. */
  firstRound?: string[];
}

/** An adventure hook: the prologue, its goal, and its setup. Mirrors content/adventure.schema.json. */
export interface Adventure {
  id: string;
  status: "draft" | "ready";
  party: AdventureParty;
  title: string;
  teaser: string;
  /** Paragraphs; "{hero}" / "{heroes}" become the players' names. */
  story: string[];
  goal: string;
  /** The goal as steps the game can check, in order. Finishing the last one wins. */
  quest?: QuestStep[];
  /** What finishing the quest brings, for every hero still in the game. */
  reward?: Outcome;
  /** The quest fails if it isn't finished by the end of this round. */
  deadline?: { byRound: number };
  /** What failing the quest (out of time) brings, for every hero. */
  failure?: Outcome;
  setup?: AdventureSetup;
  notes?: string;
}

/**
 * One step of an adventure's quest. It's done when a hero meets everything in `done` at once
 * (standing at a place, carrying an item, holding enough gold), when an encounter's outcome
 * says so (a "quest" effect), or when the Keeper marks it done. Without `done`, only those two.
 */
export interface QuestStep {
  id: string;
  text: string;
  done?: { at?: string; has?: string; gold?: number };
}

export type Stats = Record<StatKey, number>;

/** A hero class players pick when starting a game. Mirrors content/hero.schema.json. */
export interface HeroClass {
  id: string;
  status: "draft" | "ready";
  name: string;
  description: string;
  stats: Stats;
  /** Starting and maximum health. */
  health: number;
  /** The class's own resource, and how much of it they start with (also the most they hold). */
  resource: ResourceKey;
  resourceAmount: number;
  /** The class's special abilities, paid for from its resource. */
  abilities?: Ability[];
  inventory?: Effect[];
  notes?: string;
}

/**
 * An ability's job. Every class has one of each: Strike hits harder, Guard keeps someone alive,
 * Trick bends a scene, Signature is the class's big moment. Costs follow the role.
 */
export type AbilityRole = "strike" | "guard" | "trick" | "signature";

/**
 * A class ability: what it costs, what it does in plain words, and what the app does with it.
 * Anything the app doesn't do (an enemy losing a turn, poison) is played out at the table.
 */
export interface Ability {
  name: string;
  role?: AbilityRole;
  /** How much of the class resource it takes. */
  cost?: number;
  /** What it does at rank 1, in plain words. */
  effect?: string;
  /** What each rank after the first adds, in plain words (e.g. "+3"). */
  perRank?: string;
  /** Adds to the total of the hero's next roll of these stats: the rules' bonus per rank. */
  bonus?: { stats: StatKey[] };
  /** Heals a hero: this many six-sided dice, plus the rules' bonus per rank. */
  heal?: { dice: number; target: "self" | "any" };
}

/**
 * Where an item is worn. Two-handed items fill both hands. A hero can wear 2 necklaces and
 * 10 rings, and one of everything else.
 */
export type ItemSlot =
  | "head"
  | "torso"
  | "belt"
  | "pants"
  | "feet"
  | "mainHand"
  | "offHand"
  | "twoHanded"
  | "necklace"
  | "ring";

/** An item that does something while worn. Mirrors content/item.schema.json. */
export interface ItemDefinition {
  name: string;
  description?: string;
  /** Where it's worn. Items without one just ride in the pack. */
  slot?: ItemSlot;
  /** Added to the hero's stats while they wear it. */
  stats?: Partial<Stats>;
  /** Used up when it's used; identical ones stack in one pocket. */
  consumable?: boolean;
  /** Skulduggery it grants while worn: free tries at locks, and simpler locks. */
  skulduggery?: number;
}

/** The XP each kind of success earns. Mirrors xpRewards in content/rules.json. */
export interface XpRewards {
  roll: number;
  luck: number;
  classOption: number;
  combat: number;
  challenge: number;
  lockpick: number;
  miniBoss: number;
  boss: number;
}

/** How big a tile's rune locks are. */
export interface LockSize {
  dials: number;
  /** How many different runes the dials carry. */
  runes: number;
  attempts: number;
}

/** Levels and what they bring. Mirrors levels in content/rules.json. */
export interface Levels {
  max: number;
  /** The total XP each level needs, from level 2 up. */
  xp: number[];
  /** Stat points each new level gives. */
  statPoints: number;
  /** Every `every`th level gives `points` instead. */
  bonusStatPoints: { every: number; points: number };
  /** Ability picks: some at the start, then at `from` and every `every` levels after. */
  abilities: { atStart: number; every: number; from: number; ranks: number; bonusPerRank: number };
}

/** One step on the difficulty scale: its name, and the lowest number that's called it. */
export interface DifficultyStep {
  name: string;
  at: number;
}

/**
 * A lasting change to a hero, like becoming a vampire: its own bonuses and drawbacks, and
 * whether it can be cured. Andrew writes them in content/traits.json.
 */
export interface Trait {
  id: string;
  status: "draft" | "ready";
  name: string;
  description: string;
  /** Whether anything can cure it. Decided per trait. */
  curable: boolean;
  /** Adds to (or, below 0, takes from) the total of every roll of these stats. */
  bonus?: { stats: StatKey[]; amount: number };
  notes?: string;
}

/** Who a Keeper event reaches. */
export type EventTargets = "everyone" | "current" | "others";

/** How often the Keeper may set off an event. Unset: the defaults in rules.json. */
export interface EventLimits {
  /** Times a game. */
  perGame?: number;
  /** Rounds that must pass since the last Keeper event, of any kind. */
  cooldownRounds?: number;
  /** Not before this round. */
  fromRound?: number;
}

/**
 * A Keeper event: something the Keeper sets off for the whole table, pausing the turn. Like an
 * encounter: its scene, a mood on screen, a challenge each hero faces, and what comes of it.
 */
export interface KeeperEvent {
  id: string;
  status: "draft" | "ready";
  name: string;
  /** The scene, shown to every player. */
  text: string;
  /** What fills the screen behind the words. */
  mood: "fog" | "embers" | "storm" | "stars";
  /** Who faces it. Defaults to everyone. */
  targets?: EventTargets;
  /** What each hero faces: a quicktime, a roll, or nothing (the outcome just happens). */
  challenge?: QuicktimeAction | RollAction;
  /** What comes of it for a hero who succeeds (or, with no challenge, for everyone). */
  success?: Outcome;
  failure?: Outcome;
  limits?: EventLimits;
  notes?: string;
}

/**
 * A hub: a place to get your bearings and choose where to go (a city's main square, a
 * cemetery). Choosing doesn't end the turn: the hero plays the encounter there.
 */
export interface Hub {
  /** The question under the scene. Defaults to "Where would you like to head to?" */
  prompt?: string;
  destinations: HubDestination[];
}

/** Somewhere a hub leads: one encounter, or a draw from a location. */
export interface HubDestination {
  id: string;
  text: string;
  label?: string;
  encounter?: string;
  /** "tileId.locationId". */
  location?: string;
}

/** Side quests come from encounters; personal ones are chosen at hero creation. */
export type QuestKind = "side" | "personal";

/**
 * A side or personal quest (content/quests.json): its steps, where it starts, how long it may
 * take, and what comes of finishing or failing it. The adventure's own quest is the main one.
 */
export interface Quest {
  id: string;
  status: "draft" | "ready";
  kind: QuestKind;
  name: string;
  description: string;
  /** Personal quests: the classes that can choose it. Unset: any. */
  classes?: string[];
  /** Where it starts: shown in the quest log. */
  start?: { location?: string; region?: string; named?: string };
  steps: QuestStep[];
  /** Fails if not done by then: `rounds` after it starts, or by round `byRound`. */
  deadline?: { rounds?: number; byRound?: number };
  /** What finishing it brings (its effects go to whoever holds it). */
  reward?: Outcome;
  /** What failing it costs. */
  failure?: Outcome;
  notes?: string;
}

/** A kind of encounter, from Common to Legendary: its badge, and how often it's drawn. */
export interface Rarity {
  id: string;
  name: string;
  /** Out of all the rarities' odds together. */
  odds: number;
  /** Its badge's colour. */
  color: string;
}

/** Day and night take turns, a few rounds each. */
export type TimeOfDay = "day" | "night";

/** Table rules the app shows at the right moment. Mirrors content/rules.json. */
export interface Rules {
  status: "draft" | "ready";
  /** When a hero's health reaches 0: what's shown, and what coming back costs. */
  death: {
    text: string;
    goldCost: number;
    renownCost: number;
  };
  /** Class resources: the share of the pool regained at the start of each of a hero's turns. */
  resources: { regainShare: number };
  /** Day and night take turns, this many rounds each. Optional so older rules still load. */
  dayNight?: { roundsEach: number };
  /**
   * The Ethereal Realm's portal: the first round it may open (a random one between these),
   * how many rounds it stays open, how long until it opens again when no one went in, and
   * how many turns the journey inside takes.
   */
  realm?: { firstRound: [number, number]; openRounds: number; reopenAfter: number; steps: number };
  /** Keeper events' limits, unless an event sets its own. Optional so older rules still load. */
  keeperEvents?: Required<Pick<EventLimits, "perGame" | "cooldownRounds">>;
  /** The kinds of encounter, commonest first. Optional so older rules still load. */
  rarities?: Rarity[];
  /** How many items a hero can carry besides what they wear. */
  packSize: number;
  /** Renown titles: one for every `step` of renown, and darker ones below 0. */
  renown: { step: number; titles: string[]; infamy: string[] };
  /** Levels: the XP each needs, and what each brings. */
  levels: Levels;
  /** The XP each kind of success earns, automatically. */
  xpRewards: XpRewards;
  /** Rune locks by tile: dials, runes and tries. */
  locks: Record<LockTier, LockSize>;
  /** The most any stat can be: the most dice a hero rolls. Gear adds to the total instead. */
  statCap: number;
  /** What a test's difficulty is called, easiest first. */
  difficulties: DifficultyStep[];
  notes?: string;
}
